INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(26, 'koKR', 'Lekcja do odrobienia', '$N, z wielką radością śledzę twoje postępy. Bez wątpienia wyrastasz na cenionego obrońcę natury.$B$BNadszedł czas, byś $gpoznał:poznała; jeszcze jeden z wielu zwierzęcych aspektów, w które Cenarius pobłogosławił nas zdolnością przemiany – taki, który daje władzę i panowanie nad wodą. W tym celu musisz udać się do wioski Nocny Azyl w Gaju Luny i porozmawiać z Dendrite\'em Gwiezdnym Płomieniem z Kręgu Cenariona. On poprowadzi cię dalej.', 'Porozmawiaj z Dendrite\'em Gwiezdnym Płomieniem w wiosce Nocny Azyl w Gaju Luny.', '', '', '', '', '', '', 0),
(27, 'koKR', 'Lekcja do odrobienia', '$N, z wielką radością śledzę twoje postępy. Bez wątpienia wyrastasz na cenionego obrońcę natury.$B$BNadszedł czas, byś $gpoznał:poznała; jeszcze jeden z wielu zwierzęcych aspektów, w które Cenarius pobłogosławił nas zdolnością przemiany – taki, który daje władzę i panowanie nad wodą. W tym celu musisz udać się do wioski Nocny Azyl w Gaju Luny i porozmawiać z Dendrite\'em Gwiezdnym Płomieniem z Kręgu Cenariona. On poprowadzi cię dalej.', 'Porozmawiaj z Dendrite\'em Gwiezdnym Płomieniem w wiosce Nocny Azyl w Gaju Luny.', '', '', '', '', '', '', 0),
(31, 'koKR', 'Postać morska', '$GUkończyłeś:Ukończyłaś; wszystkie lekcje, które musi przejść każdy młody druid, zanim przybierze postać wodną. Wróć teraz do swojego nauczyciela, Turaka Runicznego Totemu, w Gromowych Urwiskach. Pokaż mu wisior i udowodnij, że $gjesteś gotów:jesteś gotowa; przyjąć to, czego ma cię nauczyć. On dokończy twoje szkolenie i pozwoli ci stać się jednym z wodą.$B$BŻegnaj, $gmłody druidzie:młoda druidko;. Jeszcze porozmawiamy.', 'Wróć do Gromowych Urwisk i pokaż Turakowi Runicznemu Totemowi wisior lwa morskiego.', '', '', '', '', '', '', 0),
(32, 'koKR', 'Powstanie silithidów', 'Proszę, oto twój raport. Usilnie radzę ci zanieść go komuś, kto ma praktyczną wiedzę w tych sprawach.$B$BZnam pewnego trolla uczonego, nazywa się Zilzibin Bębnoznawca. Spędził mnóstwo czasu na badaniu form życia, które występują wyłącznie w ekosystemie Azeroth, a do tego jest historykiem! Jeśli chcesz, żeby ktoś pomógł ustalić, czym dokładnie jest to zagrożenie i jak je powstrzymać, daj mu ten raport. Będziemy potrzebować wszelkiej możliwej pomocy.$B$BZil mieszka w domu na drugim poziomie Dziury w Orgrimmarze.', 'Zanieś raport Zilzibinowi Bębnoznawcy w Orgrimmarze.', '', '', '', '', '', '', 0),
(162, 'koKR', 'Powstanie silithidów', 'Proszę cię, zanieś ten raport komuś, kto zna się na takich sprawach.$B$BZnam pewną uczoną z nocnych elfów, Gracinę Moc Ducha. Spędziła mnóstwo czasu na badaniu form życia występujących tylko w ekosystemie Azeroth, a do tego jest historyczką! Jeśli chcesz, żeby ktoś pomógł ustalić, czym dokładnie jest to zagrożenie, a przede wszystkim jak je powstrzymać, oddaj jej ten raport. Będziemy potrzebować pomocy.$B$BZ tego, co ostatnio słyszałem, mieszka w Świątyni Księżyca w Darnassus.', 'Zanieś raport z analizy owadów Gracinie Mocy Ducha w Darnassus.', '', '', '', '', '', '', 0),
(730, 'koKR', 'Kłopoty na Mrocznym Wybrzeżu?', 'Jak miło widzieć kogoś takiego jak ty, kto interesuje się wielkimi archeologicznymi cudami naszego świata.$b$bNasi przyjaciele z Przymierza często zbywają naszą pracę jako zwykłe hobby. Wielu jednak nie dostrzega, że niedawne odkrycia w Khaz Modanie dowiodły, iż całemu Azeroth, od Lordaeronu po Kalimdor, zagraża wielka i potężna siła.$b$bNajbardziej martwię się o ekipę, którą wysłałem na Mroczne Wybrzeże. Od tygodni nie dali znaku życia.$b$bUdaj się do Auberdine i poszukaj wskazówek, gdzie mogą być.', 'Udaj się do Auberdine i poszukaj śladów krasnoludzkiej ekipy wykopaliskowej.', '', '', '', '', '', '', 0),
(741, 'koKR', 'Roztargniony poszukiwacz', 'Więc poszukiwacz chce wysłać tajemniczą skamieniałość do Ligi Odkrywców w Darnassus? Nie czuję się dobrze z myślą, że miałabym opuścić Mroczne Wybrzeże bez niego.$b$bProszę, $n, zanieś tajemniczą skamieniałość głównemu archeologowi Siwowąsowi w Darnassus.', 'Zanieś tajemniczą skamieniałość głównemu archeologowi Siwowąsowi w Darnassus.', '', '', '', '', '', '', 0),
(942, 'koKR', 'Roztargniony poszukiwacz', 'Ta skamieniałość łudząco przypomina tę, którą widziałem kiedyś w Żelaznej Kuźni. Przywiózł ją na doroczną konferencję Ligi Odkrywców archeolog nazwiskiem Flagongut. Wierzył, że skamieniałość kryje w sobie moc, którą da się jakoś uwolnić.$b$bZ tego, co ostatnio słyszałem, Flagongut zaszył się w tawernie „Głęboka Woda” w Przystani Menethilów i czeka na eskortę do Wykopalisk Whelgara. Odszukaj go i pokaż mu skamieniałość Remtravela. Może zdoła odkryć tajemnice przeszłości.$b$bPowodzenia w drodze!', 'Zanieś tajemniczą skamieniałość archeologowi Flagongutowi w Przystani Menethilów.', '', '', '', '', '', '', 0),
(952, 'koKR', 'Gaj Pradawnych', 'Skoro $gmiałeś:miałaś; dość czasu, by nosić wiadomości dla Drzewa Wyroczni, to z pewnością mogę cię poprosić o dostarczenie wiadomości do Gaju Pradawnych na Mrocznym Wybrzeżu, na południe od Auberdine.$b$bNajpewniej trzeba będzie załatwić sobie lot na hipogryfie, ale wierzę, że sobie z tym poradzisz. Zanieś to Onu, Pradrzewcowi wiedzy. Czeka na wieść ode mnie, tak jak ja czekałem na wieści z Polany Wyroczni.', 'Dostarcz wiadomość Fandrala Onu w Gaju Pradawnych na Mrocznym Wybrzeżu, na południe od Auberdine.', '', '', '', '', '', '', 0),
(1037, 'koKR', 'Velinde Gwiezdna Pieśń', 'Velinde Gwiezdna Pieśń była moją poprzedniczką tu, w Jesionowej Kniei. Z początku wydawało się, że panuje nad sytuacją w Spaczonej Kniei, ale jej starania stopniowo słabły. Pewnego dnia po prostu zniknęła.$b$bPrzysłano mnie tutaj, abym kontynuowała jej pracę. Obawiam się jednak, że nic nie wiem o tej kapłance. Być może Thyn\'tel Tkaczka Ostrzy, jedna z dowódczyń Strażniczek, zna więcej szczegółów jej zniknięcia, w które mnie nie wtajemniczono.$b$bZ pewnością zrozumie wagę takich informacji.', 'Porozmawiaj z Thyn\'tel Tkaczką Ostrzy na Tarasie Wojowników w Darnassus.', '', '', '', '', '', '', 0),
(1038, 'koKR', 'Rzeczy Velinde', 'Księga Mel\'Thandris ci to pokazała? Przypuszczam, że nie zaszkodzi, jeśli przejrzysz jej rzeczy. Ten klucz otworzy skrzynię, w której przechowujemy jej dobytek, w Kwaterze Strażniczek. Prowadziła dziennik swoich obowiązków; jeśli jest coś do odkrycia, to właśnie w nim.$b$bMuszę ci powiedzieć, że Strażniczki wierzą, iż miała własne powody, by odejść, i spodziewają się, że może wrócić w każdej chwili. Kapłanka wiele w przeszłości zrobiła, by zasłużyć na nasze zaufanie.', 'Przeszukaj skrzynię Velinde, znajdź jej dziennik, a następnie zanieś go razem z kluczem Thyn\'tel Tkaczce Ostrzy w Darnassus.', '', 'Wróć do Thyn\'tel Tkaczki Ostrzy na Tarasie Wojowników w Darnassus.', '', '', '', '', 0),
(1039, 'koKR', 'Port na Pustkowiach', 'Zapadka to jedyny port na Pustkowiach. Najpewniej Velinde znalazła tam statek handlowy, który zabrał ją do Zatoczki Czarnej Wody we Wschodnich Królestwach. Mieliśmy niewiele do czynienia z goblinami, które prowadzą port, ale kapitan portu powinien wiedzieć, kto przypływa i odpływa statkami.$b$bIdź drogą na południowy wschód przez Jesionową Knieję, a dotrzesz na Pustkowia. Uważaj, $n, tamte ziemie patrolują wojownicy Hordy. W porcie będziesz jednak $gbezpieczny:bezpieczna;.', 'Porozmawiaj z kapitanem portu Dizzywigiem w Zapadce na Pustkowiach.', '', '', '', '', '', '', 0),
(1044, 'koKR', 'Odpowiedzi na pytania', 'Poradzimy sobie z problemem worgenów, nie martw się. Zło, które twoja przyjaciółka sprowadziła do naszych lasów, zostanie powstrzymane, a ja nie żywię do niej urazy za jej czyny. W tych czasach dzieją się dziwne rzeczy, $n, a ciemność nie zna wytchnienia.$b$bNie będę cię dłużej zatrzymywał. Podejrzewam, że są inni, którzy powinni usłyszeć o tym, co $gznalazłeś:znalazłaś; w kopalniach Kniei Zmierzchu.', 'Wróć do Thyn\'tel Tkaczki Ostrzy w Darnassus.', '', '', '', '', '', '', 0),
(1081, 'koKR', 'Audiencja u Tyrande', '$N, jestem pewna, że sama Tyrande Szept Wiatru zechce ci podziękować za udział w tej misji.$B$BMoże na pierwszy rzut oka tego nie widać, ale to, co $gpomogłeś:pomogłaś; zapoczątkować, może znacznie umocnić naszą pozycję w Górach Szponogłazach.$B$BJeśli uważasz się za naszego sojusznika w walce z tymi okrucieństwami, udaj się do Tyrande w Świątyni Księżyca w Darnassus.', 'Odszukaj Tyrande Szept Wiatru w Darnassus.', '', '', '', '', '', '', 0),
(1123, 'koKR', 'Rabine Saturna', 'W tej sprawie Rabine Saturna, zarządca Opiekuna Remulosa w Gaju Luny, szuka pomocy w badaniu rozległych pustkowi daleko na zachód od Tanaris i Un\'Goro. Znajdziesz go w Nocnym Azylu, głównej osadzie Gaju Luny.$B$BChcę, byś $gzrozumiał:zrozumiała;, jak ważna jest twoja obecność. Między nocnymi elfami z Darnassus a Kręgiem Cenariona w Gaju Luny narastają napięcia. W sprawach z tamtejszym Kręgiem wznieś się ponad podziały między rasami i sięgnij do mądrości przodków, $N. Powodzenia.', 'Porozmawiaj z Rabine\'em Saturną w wiosce Nocny Azyl w Gaju Luny. Gaj Luny leży między Spaczoną Knieją a Zimozdrojem; prowadzi do niego ścieżka z Warowni Pyskodrzewnych.', '', '', '', '', '', '', 0),
(1142, 'koKR', 'Gasnące życie', 'Niewiele mi już zostało... tak... tak... słaby...$b$b...d-d-dzielny krasnolud Lonebrow został wysłany, by o-o-ostrzec Falfindela...$b$bAle zanim... u-u-umrę...$b$b...moja żona, Treshala... jej wisior, który nas łączył... skradziony... przez jednego z p-p-plugawych napastników...$b$bZnajdź go, p-p-proszę... i zwróć Treshali w Darnassus...$b$b...razem z w-w-wieścią o mojej samotnej... śmierci.', 'Znajdź wisior Treshali i zwróć go Treshali Ugornemu Strumieniowi w Darnassus.', '', 'Wróć do Treshali Ugornego Strumienia w Enklawie Cenariona w Darnassus.', '', '', '', '', 0),
(1198, 'koKR', 'W poszukiwaniu Thaelrida', 'Krąży ostatnio wiele plotek o sojuszu Młota Zmierzchu z nagami w Czarnych Głębinach na wybrzeżu Jesionowej Kniei.$b$bMoim zadaniem z ramienia Argentowego Brzasku jest zbieranie jak największej ilości informacji, abyśmy wiedzieli, kiedy i gdzie potrzebna jest pomoc.$b$bMinęły już tygodnie, odkąd wysłałem zwiadowcę, by sprawdził, co się dzieje w Czarnych Głębinach. Gwardzista Argentu Thaelrid wciąż nie złożył raportu.$b$bPozostali moi zwiadowcy są zajęci pilnymi sprawami.$b$bOdszukaj Thaelrida i pomóż mu w moim imieniu, $n.', 'Odszukaj gwardzistę Argentu Thaelrida w Czarnych Głębinach.', '', '', '', '', '', '', 0),
(1199, 'koKR', 'Upadek Zmierzchu', 'Wzmocnieni pradawnymi obrzędami chaotycznych Przedwiecznych Bogów, członkowie Młota Zmierzchu dążą do powrotu swoich mrocznych patronów i chcą szerzyć śmierć i grozę na całym świecie.$b$bSądzimy, że Młot Zmierzchu sprzymierzył się z nagami i gromadzi siły w Czarnych Głębinach na wybrzeżu Jesionowej Kniei.$b$bJakikolwiek nikczemny plan warzy się w głębinach starej świątyni, trzeba go udaremnić.$b$bWypowiedz wojnę Młotowi i przynieś dowody swoich czynów. Twoje starania zostaną sowicie wynagrodzone.', 'Przynieś 10 wisiorów zmierzchu gwardziście Argentu Manadosowi w Darnassus.', '', 'Wróć do gwardzisty Argentu Manadosa na Tarasie Rzemieślników w Darnassus.', '', '', '', '', 0),
(1200, 'koKR', 'Nikczemność w Czarnych Głębinach', 'Opuściły mnie siły. Potrzebuję twojej pomocy!$b$bDawno temu stała tu wielka świątynia Eluny. Ale nieszczęście doprowadziło ją do ruiny, gdy spaczenie jednego z Przedwiecznych Bogów przesączyło się spod ziemi i skaziło świętą księżycową studnię.$b$bZ wód wynurzył się Aku\'mai, sługa Przedwiecznego.$b$bKultyści Młota Zmierzchu sprzymierzyli się z nagami, by zająć te tereny. Kultyści pod wodzą Kelrisa składają niewinnych w ofierze Aku\'mai, by zyskać moc.$b$bZabij Kelrisa i zanieś jego głowę Selgormowi w Darnassus, $N. Proszę.', 'Zanieś głowę Władcy Zmierzchu Kelrisa strażnikowi Brzasku Selgormowi w Darnassus.', '', 'Wróć do strażnika Brzasku Selgorma w Darnassus.', '', '', '', '', 0),
(1582, 'koKR', 'Kamizelka księżycowej poświaty', 'My w Darnassus, a zwłaszcza my, rzemieślnicy, mamy mnóstwo pracy. Młodzi poszukiwacze przygód garną się, by sprawdzić się w dziczy, i wciąż potrzebują zaopatrzenia.$B$BJeśli pomożesz mi zrealizować zamówienia na wyroby skórzane, to może nauczę cię zaawansowanej techniki garbarskiej.', 'Przynieś 1 parę rękawic z tłoczonej skóry, 5 par butów z tłoczonej skóry i 5 płaszczy z tłoczonej skóry Lotherias w Darnassus.', '', 'Wróć do Lotherias w Darnassus.', '', '', '', '', 0),
(1683, 'koKR', 'Vorlus Nikczemne Kopyto', 'Zanim zacznę cię uczyć, musisz mi pokazać swoją determinację.$B$BSatyr Vorlus Nikczemne Kopyto znalazł jedną z naszych odległych księżycowych studni, na południowy wschód od Kurhanu Ban\'ethil. Pluska się teraz w niej, kalając jej czyste wody swoim plugastwem.$B$BZnajdź Vorlusa przy księżycowej studni i zniszcz go. Przynieś mi jego róg jako dowód, a rozpocznę twoje zaawansowane szkolenie wojownika.$B$BŚcieżka do księżycowej studni jest dobrze ukryta, $N, ale jeśli pozostaniesz $gskupiony:skupiona; i $gczujny:czujna;, odnajdziesz ją.', 'Przynieś róg Vorlusa Elanarii w Darnassus.', '', 'Wróć do Elanarii na Tarasie Wojowników w Darnassus.', '', '', '', '', 0),
(1686, 'koKR', 'Cień Elury', 'Wiele się $gnauczyłeś:nauczyłaś;, $N. Teraz wykujemy dla ciebie broń. Broń wojownika.$B$BW tym celu musisz udać się na Mroczne Wybrzeże.$B$BDawno temu przy latarni morskiej w Auberdine rozbił się o skały statek, rozrzucając po dnie morza wiele skrzyń z rudą elunitu.$B$BNajpierw musisz pokonać strażniczkę elunitu, Cień Elury. Niegdyś była kapitanem tego statku, a potem przeklęła samą siebie, by na zawsze krążyć w głębinach i strzec swojego ładunku. Pokonaj ją, zdobądź jej medalion i zbierz skrzynie zaginionego elunitu.', 'Przynieś 8 ładunków rudy elunitu i medalion Elury Elanarii w Darnassus.', '', 'Wróć do Elanarii na Tarasie Wojowników w Darnassus.', '', '', '', '', 0),
(1692, 'koKR', 'Kowal Mathiel', 'Elunit, który $gzebrałeś:zebrałaś;, umieściłam w skrzynce. Zanieś ją kowalowi Mathielowi, a on wykuje dla ciebie broń z elunitu.$B$BMathiel jest na południu, po drugiej stronie tego budynku.', 'Zanieś skrzynkę elunitu kowalowi Mathielowi.', '', '', '', '', '', '', 0),
(1693, 'koKR', 'Broń z elunitu', '', '', '', '', '', '', '', '', 0),
(1710, 'koKR', 'Spalone słońcem skorupy', 'Mój kolega, Furen Długobrody, dokonał odkrycia, które chętnie wypróbuję. Chcę je zastosować przy nowej zbroi, nad którą pracuję, bo wierzę, że techniki Furena dadzą znakomite rezultaty.$B$BPomożesz mi? Jeśli zbierzesz to, czego potrzebuję do wykonania zbroi, zrobię dodatkowy egzemplarz dla ciebie.$B$BPotrzebuję spalonych słońcem skorup jaj wiwern z Wysokiej Grzędy, które żyją na Wysokiej Grzędzie w Tysiącu Filarów. Szukaj skorup pod ich gniazdami i wróć do mnie, gdy zbierzesz ich dość.', 'Przynieś 20 spalonych słońcem skorup Mathielowi w Darnassus.', '', 'Wróć do Mathiela na Tarasie Wojowników w Darnassus.', '', '', '', '', 0),
(1711, 'koKR', 'Zbroja Mathiela', '', '', '', '', '', '', '', '', 0),
(2242, 'koKR', 'Wezwanie przeznaczenia', 'Sądzimy, że istnieje jedna istota, która mogłaby nam pomóc zrozumieć, co dzieje się z lasami Teldrassilu. Niestety próby nakłonienia jej do współpracy kończyły się katastrofą.$B$BUkrywa się na gałęzi na obrzeżach Polany Wyroczni. Wszyscy, którzy dotąd zbliżali się do tego satyra, siłą czy dyplomacją, spotkali swoją zgubę. Być może odpowiedzią jest skradanie się, $N.$B$BSprawdź, co Sethir Pradawny nosi w swoich jukach, i zdaj mi relację.$B', 'Odnajdź Sethira Pradawnego i przynieś Syurnie wszelkie wskazówki, jakie uda ci się znaleźć.$B', '', 'Wróć do Syurny na Tarasie Kupców w Darnassus.', '', '', '', '', 0),
(2518, 'koKR', 'Łzy księżyca', 'Lady Sathrah była niegdyś umiłowaną Eluny. Pełna wdzięku i czysta, pajęczyca snuła swoje srebrne nici w blasku księżyca, łapiąc w nie wieczorną mgłę. Srebrzysta rosa miała silne moce lecznicze i przechowywano ją tu, w świątyni.$B$BOstatnio jednak Sathrah popadła w szaleństwo. Zagrożone są teraz także jej przyszłe pokolenia.$B$BOdnajdź lady Sathrah, $N, i zakończ jej cierpienie. Żyje przy północnych granicach Teldrassilu, nad Jeziorem Źródlanym. Zdobądź jej srebrzyste kądziołki i przynieś mi je.', 'Kapłanka A\'moora w Świątyni Księżyca w Darnassus chce, byś $gprzyniósł:przyniosła; jej srebrzyste kądziołki lady Sathrah.', '', 'Wróć do kapłanki A\'moory w Ogrodach Świątynnych w Darnassus.', '', '', '', '', 0),
(2519, 'koKR', 'Świątynia Księżyca', 'Pewna niegdyś wspaniała istota lasu potrzebuje pomocy.$B$BTrzeba wykonać trudne zadanie.$B$BOdszukaj, proszę, kapłankę A\'moorę; ona ci wszystko wyjaśni. Znajdziesz ją na południowy wschód stąd, w Świątyni Księżyca.', 'Siostra Aquinne chce, byś $gporozmawiał:porozmawiała; z kapłanką A\'moorą w Świątyni Księżyca.', '', '', '', '', '', '', 0),
(2520, 'koKR', 'Ofiara Sathrah', 'Teraz musisz dokończyć zadanie, które ci powierzono. Weź kądziołki i złóż ofiarę lady Sathrah Elunie; pozwól wielkiej pajęczycy spocząć w pokoju.$B$BW tej świątyni znajdź centralną fontannę. Tam możesz zostawić ofiarę. Święte wody oczyszczą ją ze spaczenia, które doprowadziło Sathrah do szaleństwa.$B$BGdy to zrobisz, wróć do mnie.', 'Kapłanka A\'moora chce, byś $gzłożył:złożyła; srebrzyste kądziołki lady Sathrah przy fontannie wewnątrz świątyni, a potem do niej $gwrócił:wróciła;.', 'Złóż ofiarę przy fontannie', 'Wróć do kapłanki A\'moory w Darnassus.', '', '', '', '', 0),
(2853, 'koKR', 'Mistrz dzikiej skóry', 'Cóż, $n, jesteś uosobieniem pracowitości. Został ostatni wykrój zbroi z dzikiej skóry; pozostałe już $gopanowałeś:opanowałaś;. Nie każę ci się niepotrzebnie trudzić dla tego wykroju. $GZasłużyłeś:Zasłużyłaś; na niego w pełni, a nawet z nawiązką... ale nie mogę ci go dać osobiście. Musi cię nagrodzić mój nauczyciel, ten, który wprowadził mnie w rzemiosło.$B$BZanieś ten list Telonisowi; uczy garbarstwa w Darnassus. Pokaż mu list i pozwól, by uznał cię za równego sobie, tak jak ja.', 'Oddaj list Pratta Telonisowi, mistrzowi garbarstwa w Darnassus.', '', '', '', '', '', '', 0),
(2860, 'koKR', 'Mistrz dzikiej skóry', '$n, nauczyłem cię wszystkiego, czego mogłem. Pozostał jednak jeszcze jeden wykrój zbroi z dzikiej skóry. Nie będę kazał ci się niepotrzebnie trudzić, by go zdobyć; w pełni na niego $gzasłużyłeś:zasłużyłaś;, i to z nawiązką. Tym wykrojem nie mogę się jednak z tobą swobodnie podzielić.$B$BTo moja nauczycielka, ta, która wprowadził mnie w rzemiosło, musi cię nagrodzić. Zanieś ten list Unie; uczy kaletnictwa w Gromowych Urwiskach. Pokaż jej list i pozwól, by uznała cię za $grównego:równą; sobie, tak jak ja.', 'Oddaj list Jangdora Unie, mistrzyni kaletnictwa w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(2970, 'koKR', 'Wymierzanie sprawiedliwości', 'Jak już ci powiedziała, Kindal i ja zaniesiemy teraz walkę do Ponurego Totemu. Razem powinnyśmy dać radę wyeliminować część taurenów bez większego ryzyka dla nas samych, ale chętnie przyjmiemy pomoc, jeśli masz ochotę i siły.$B$BWidzisz obóz pod nami, ale więcej jest na wschodzie. Własnymi metodami zadaj taurenom jak największe straty. Spotkamy się tu wszyscy, gdy poczują ukąszenie strzał Kindal i twojej broni.', 'Zabij 12 przyrodników Ponurego Totemu, 10 najeźdźców Ponurego Totemu i 6 szamanów Ponurego Totemu, a następnie wróć do Jer\'kai Tkaczki Księżyca w Feralas.', '', 'Wróć do Jer\'kai Tkaczki Księżyca w Feralas.', '', '', '', '', 0),
(2972, 'koKR', 'Wymierzanie sprawiedliwości', 'Tu, w dziczy, Kindal i ja mamy skromne środki, by wynagrodzić twoją pomoc, ale nie chcemy, żebyś $gczuł:czuła; się $gniedoceniony:niedoceniona;. Weź mój sygnet. Jeśli kiedyś znajdziesz się wśród konarów Teldrassilu, udaj się do Świątyni Księżyca w sercu Darnassus. Znajdziesz tam moją Wielką Kapłankę, Tyrande Szept Wiatru. Sygnet da jej znać, że nic nam nie jest, i uwiarygodni twoją opowieść.$B$BOboje ci dziękujemy, $N.', 'Zanieś sygnet Jer\'kai Wielkiej Kapłance Tyrande Szept Wiatru w Darnassus.', '', '', '', '', '', '', 0),
(3369, 'koKR', 'W koszmarach', 'Ten odłamek kryje wielkie sekrety; to czysta esencja Szmaragdowego Snu. Jednak to, co w nim widzę, nie jest snem; taką wizję nazwałoby się koszmarem.$B$BNie chcę cię niepokoić, $N, ale sądzę, że najlepiej będzie, jeśli jak najszybciej oddasz ten odłamek w ręce mądrego druida.$B$BMusisz udać się do Hamuula Runicznego Totemu na Wzniesieniu Starszych. Udaj się do Gromowych Urwisk. Więcej nie mogę powiedzieć.', 'Zanieś odłamek koszmaru Hamuulowi Runicznemu Totemowi na Wzniesieniu Starszych.', '', '', '', '', '', '', 0),
(3370, 'koKR', 'W koszmarach', 'Ten odłamek skrywa wielkie tajemnice; to czysta esencja Szmaragdowego Snu. Jednak to, co w nim widzę, nie jest snem. Taką wizję nazwałoby się raczej koszmarem.$B$BNie chcę cię niepokoić, $N, ale sądzę, że najlepiej będzie, jeśli jak najszybciej przekażesz ten odłamek w ręce mądrego druida...$B$BMusisz odnaleźć Mathrengyla Niedźwiedziego Kroka z Kręgu Cenariona. Udaj się do Darnassus. Więcej nie mogę powiedzieć.', 'Zanieś odłamek koszmaru Mathrengylowi Niedźwiedziemu Krokowi w Darnassus.', '', '', '', '', '', '', 0),
(3377, 'koKR', 'Modlitwa do Eluny', 'Pomożesz mi, $gśmiertelniku:śmiertelniczko;? Wysłuchaj mojej opowieści.', 'Wysłuchaj opowieści Zamaela.', 'Opowieść Zamaela', 'Wróć do Zamaela Lunthistle\'a na Grani Ognistej Straży w Płonącym Wąwozie.', '', '', '', '', 0),
(3378, 'koKR', 'Modlitwa do Eluny', 'Czy mi pomożesz, $gśmiertelniku:śmiertelniczko;? Czy odnajdziesz modlitwę do Eluny?$B$BJak mówiłem, modlitwę wyryto na złotej tabliczce. Któryś z tych bałwochwalczych łotrów musi mieć ją przy sobie.$B$BJeśli odzyskasz moją modlitwę, zanieś ją Astarii Astrowidzącej w Darnassus. Nieważne, że moja wiara odrodziła się po niezliczonych złych czynach, jakich dopuściłem się wobec tego świata i jego mieszkańców – moja modlitwa musi zostać wysłuchana. Rozgrzeszenia spodziewam się najmniej.', 'Odnajdź Modlitwę do Eluny i zanieś ją Astarii Astrowidzącej w Darnassus.$B', '', 'Wróć do Astarii Astrowidzącej w Ogrodach Świątynnych w Darnassus.', '', '', '', '', 0),
(3761, 'koKR', 'Ziemia z Un\'Goro', 'Podobno ziemia z Krateru Un\'Goro jest nasycona silnymi magicznymi właściwościami. Krąg Cenariona chce zbadać tę ziemię w dużych ilościach; wyrusz w dzicz Un\'Goro i zdobądź jej tyle, ile potrzeba do dalszych badań.$B$BTę żyzną ziemię znajdziesz tu i ówdzie w kopczykach, a niektóre bestie mogą mieć przy sobie próbki nadające się do użytku. Zanieś je wszystkie na zewnątrz do Ghedego – wystarczy wypatrywać kopców ziemi i taurena, który wykrzykuje rozkazy. Ma dobre intencje, tylko lepiej go nie rozdrażniać!', 'Przynieś 20 próbek ziemi z Un\'Goro Ghedemu na Wzniesieniu Starszych w Gromowych Urwiskach.', '', 'Wróć do Ghedego przy Ujęciu Wody Dzikogrzywych w Mulgorze.', '', '', '', '', 0),
(3764, 'koKR', 'Ziemia z Un\'Goro', 'Podobno ziemia Krateru Un\'Goro jest nasycona silnymi właściwościami magicznymi. Chcę oddzielić fakty od bajek. Wyrusz w dzicz Un\'Goro i zdobądź dość dobrych próbek ziemi do naszych dalszych badań.$B$BMożesz uważać, że zbieranie próbek jest poniżej twojej godności; taka postawa nie zjedna ci jednak ani mojej sympatii, ani sympatii Kręgu Cenariona. Zanieś próbki Jenalowi, który bez wątpienia marnuje czas na zewnątrz, za tym drzewem – szukaj po prostu kupek ziemi. On zajmie się logistyką, nie ja.', 'Przynieś 20 próbek ziemi z Un\'Goro Jenalowi w Enklawie Cenariona w Darnassus.', '', 'Wróć do Jenala w Enklawie Cenariona w Darnassus.', '', '', '', '', 0),
(3781, 'koKR', 'Badania nad jutroziarnem', 'W tak zwanej sakiewce wiecznej zieleni hodujemy nasiona tharlendris w ziemi z Krateru Un\'Goro. Z nasion tych wyrastają rozmaite, przypadkowe zioła o silnych właściwościach. Jednym z nich jest jutroziarno, tajemnicze zioło, o którym niewiele wiemy. Zamierzam zgłębić tę tajemnicę.$B$BZanieś to Mathrengylowi na dole, a da ci trochę nasion, żebyś $gmógł:mogła; zacząć. Jeśli ci się skończą, będziesz $gmusiał:musiała; dokupić je u niego.', 'Zanieś bon na nasiona od arcydruida Mathrengylowi Niedźwiedziemu Krokowi w Enklawie Cenariona w Darnassus.', '', '', '', '', '', '', 0),
(3782, 'koKR', 'Badania nad jutroziarnem', 'W tak zwanej sakiewce wiecznej zieleni hodujemy nasiona tharlendris w ziemi z Krateru Un\'Goro. Z nasion tych wyrastają rozmaite, przypadkowe zioła o silnych właściwościach. Jednym z nich jest jutroziarno, tajemnicze zioło, o którym niewiele wiemy; bardzo liczę na to, że zgłębię tę tajemnicę dla Kręgu.$B$BZanieś ten bon mojej córce Bashanie, a da ci trochę nasion, żebyś $gmógł:mogła; nam pomóc. Jeśli ci się skończą, będziesz $gmusiał:musiała; dokupić więcej u niej.', 'Zanieś bon na nasiona Bashanie Runicznemu Totemowi w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(3785, 'koKR', 'Badania nad jutroziarnem', 'Oto sakiewka wiecznej zieleni, której będziesz potrzebować do nasion tharlendris. Musisz też mieć przy sobie próbki ziemi z Un\'Goro, które posłużą nasionom za nawóz. Gdy będziesz mieć wszystko, po prostu użyj sakiewki – ona zajmie się resztą.$B$BGdy zbierzesz dość jutroziarna, przynieś je tutaj, do mnie, do enklawy. I proszę, nie niepokój arcydruida; to bardzo zajęty mąż i nie trzeba mu przeszkadzać za każdym razem, gdy ktoś wraca z kolejną porcją jutroziarna!', 'Użyj sakiewki wiecznej zieleni z paczką nasion tharlendris i dwiema próbkami ziemi z Un\'Goro, aby spróbować wyhodować jutroziarno.$B$BPrzynieś 10 sztuk jutroziarna Mathrengylowi Niedźwiedziemu Krokowi w Darnassus.', '', 'Wróć do Mathrengyla Niedźwiedziego Kroka w Enklawie Cenariona w Darnassus.', '', '', '', '', 0),
(3786, 'koKR', 'Badania nad jutroziarnem', 'Oto sakiewka wiecznej zieleni, której będziesz potrzebować do nasion tharlendris. Musisz też mieć przy sobie próbki ziemi z Un\'Goro, które posłużą nasionom za nawóz. Gdy będziesz mieć wszystko, po prostu użyj sakiewki – ona zajmie się resztą.$B$BGdy zbierzesz dość jutroziarna, przynieś je do mnie, tutaj, na Wzniesienie Starszych. I proszę, nie niepokój arcydruida; będzie bardzo zajęty badaniami, a do tego ma mnóstwo innych zmartwień!', 'Użyj sakiewki wiecznej zieleni z paczką nasion tharlendris i dwiema próbkami ziemi z Un\'Goro, aby spróbować wyhodować jutroziarno.$B$BPrzynieś 10 sztuk jutroziarna Bashanie Runicznemu Totemowi w Gromowych Urwiskach.', '', 'Wróć do Bashany Runicznego Totemu na Złotych Równinach w Mulgorze.', '', '', '', '', 0),
(3803, 'koKR', 'Jutroziarno dla Darnassus', '', '', '', 'Wróć do Mathrengyla Niedźwiedziego Kroka na Teldrassilu.', '', '', '', '', 0),
(4267, 'koKR', 'Powstanie silithidów', 'Powierzam ci kopię raportu, który Raschal sporządził na temat plagi w południowo-wschodnim Feralas. Główny raport trafi do Darnassus, ale chcę, żebyś tę kopię $goddał:oddała; osobie współpracującej z Protektoratem. Nazywa się Gracina Moc Ducha; to kapłanka, która mieszka w Świątyni Księżyca w Darnassus. Ma rozległą wiedzę o tego rodzaju stworzeniach, a jeśli dostanie ten raport, wszyscy na tym skorzystamy.$B$BMożesz odejść. Powodzenia, $N; niech Elune czuwa nad nami wszystkimi.', 'Zanieś raport Raschala Gracinie Mocy Ducha w Darnassus.', '', '', '', '', '', '', 0),
(4493, 'koKR', 'Pochód silithidów', 'Wydaje się, że zamiarem silithidów, ba – sensem ich istnienia – jest pożeranie wszystkiego na swojej drodze, co nie należy do ich ekosystemu. Mają jeden cel i właśnie dlatego stanowią poważne zagrożenie dla wszelkiego życia w Azeroth.$B$BTo, co widzieliśmy do tej pory, to dopiero pierwsze etapy. Podejrzewam, że ich siła pochodzi z głębi Kalimdoru – z Krateru Un\'Goro. Udaj się do Gadżetonu na pustyni Tanaris i porozmawiaj z alchemikiem Pestlezuggiem. Opowiedz mu o mojej teorii; z pewnością pomoże nam w walce z silithidami.', 'Porozmawiaj z alchemikiem Pestlezuggiem w Gadżetonie.', '', '', '', '', '', '', 0),
(4494, 'koKR', 'Pochód silithidów', 'Wydaje się, że zamiarem silithidów, ba – sensem ich istnienia – jest pożeranie wszystkiego na swojej drodze, co nie należy do ich ekosystemu. Mają jeden cel i właśnie dlatego stanowią poważne zagrożenie dla wszelkiego życia w Azeroth.$B$BTo, co widzieliśmy do tej pory, to dopiero pierwsze etapy. Podejrzewam, że ich siła pochodzi z głębi Kalimdoru – z Krateru Un\'Goro. Udaj się do Gadżetonu na pustyni Tanaris i porozmawiaj z alchemikiem Pestlezuggiem. Opowiedz mu o mojej teorii; z pewnością pomoże nam w walce z silithidami.', 'Porozmawiaj z alchemikiem Pestlezuggiem w Gadżetonie.', '', '', '', '', '', '', 0),
(4508, 'koKR', 'Cisza przed burzą', 'Moje najnowsze ustalenia i wiedza, którą dziś tu zdobyliśmy, muszą trafić w ręce kogoś, kto może coś z nimi zrobić. Choć w Gadżetonie jesteśmy zaradni, sami temu nie podołamy.$B$BZanieś mój najnowszy raport Gracinie Mocy Ducha w Darnassus; wciąż jest w Świątyni Księżyca, prawda? Ma przyjaciół wśród grubych ryb Przymierza. Jeśli uda nam się ich w to wciągnąć, $N, może jednak wyjdziemy z tego cało.', 'Zanieś raport Pestlezugga z Un\'Goro Gracinie Mocy Ducha w Darnassus.', '', '', '', '', '', '', 0),
(4509, 'koKR', 'Cisza przed burzą', 'Moje najnowsze odkrycia i wiedza, którą dziś tu zdobyliśmy, muszą trafić w ręce, które mogą coś z nimi zrobić. Choć tu, w Gadżetonie, jesteśmy bardzo zaradni, sami temu nie podołamy.$B$BZanieś mój najnowszy raport Zilzibinowi Bębnoznawcy do Orgrimmaru; wciąż siedzi u siebie w górnej części Dziury, prawda? Ma przyjaciół wysoko w Hordzie; jeśli uda nam się ich w to wciągnąć, $N, może wyjdziemy z tego cało.', 'Zanieś raport Pestlezugga z Un\'Goro Zilzibinowi Bębnoznawcy w Orgrimmarze.', '', '', '', '', '', '', 0),
(4510, 'koKR', 'Cisza przed burzą', '$N, twoja pomoc jest nieoceniona. Bez wątpienia nadejdzie czas, gdy znów poproszę cię o wsparcie przeciwko silithidom. Musimy przetrawić to, czego dowiedzieliśmy się w Un\'Goro. Obawiam się, że myliłam się, sądząc, że silithidy wywodzą się z Un\'Goro... i że gdzieś istnieje znacznie potężniejsza siła.$B$BZanieś tę notę Idrianie w banku. Wyda ci coś z mojego skarbca, co uznaj za wyraz mojej wdzięczności. Dziękuję ci za pomoc, $gdzielny:dzielna; $N.', 'Zanieś bon bankowy Idrianie w banku w Darnassus.', '', '', '', '', '', '', 0),
(4511, 'koKR', 'Cisza przed burzą', '$N, bez ciebie nie zaszlibyśmy tak daleko. Bez wątpienia wkrótce nadejdzie czas, gdy znów poproszę cię o pomoc w walce z silithidami. Musimy przetrawić to, czego dowiedzieliśmy się w Un\'Goro; obawiam się, że myliłem się, zakładając, że silithidy pochodzą z Un\'Goro... że gdzieś istnieje ich znacznie silniejsze skupisko.$B$BZanieś ten liścik Karusowi w banku. Da ci coś z mojego skarbca – potraktuj to jako wyraz mojej wdzięczności. Dziękuję za pomoc, $gpotężny:potężna; $N.', 'Zanieś bon bankowy Karusowi w banku Orgrimmaru.', '', '', '', '', '', '', 0),
(4986, 'koKR', 'Dębowa gałąź z glifami', 'Martwa dłoń taurena druida ściska zaskakująco zdrową z wyglądu dębową gałąź. Przy bliższych oględzinach widać na korze wyryte glify o druidzkim charakterze.$B$BGdy chwytasz gałąź, czujesz, że jest ciepła w dotyku, cieplejsza, niż powinna. W twoim umyśle pojawia się obraz drzewa Teldrassil – a konkretnie Darnassus – a na końcu języka masz słowa „Krąg Cenariona”. Wygląda na to, że w gałęzi zaklęto wskazówkę, dokąd należy ją zanieść.', 'Sądząc po magii zaklętej w dębowej gałęzi z glifami, dostarczenie jej do Kręgu Cenariona w Darnassus było kolejnym krokiem, do którego dążył tauren druid. Poproś o pomoc któregoś z tamtejszych druidów.', '', '', '', '', '', '', 0),
(4987, 'koKR', 'Dębowa gałąź z glifami', 'Martwa dłoń taurena druida ściska zaskakująco zdrową z wyglądu dębową gałąź. Przy bliższych oględzinach widać na korze wyryte glify o druidzkim charakterze.$B$BGdy chwytasz gałąź, czujesz, że jest ciepła w dotyku, cieplejsza, niż powinna. W twoim umyśle pojawia się obraz Gromowych Urwisk w Mulgorze – a konkretnie Wzniesienia Starszych – a na końcu języka masz słowa „Krąg Cenariona”. Wygląda na to, że w gałęzi zaklęto wskazówkę, dokąd należy ją zanieść.', 'Sądząc po magii zaklętej w dębowej gałęzi z glifami, dostarczenie jej do Kręgu Cenariona w Gromowych Urwiskach było kolejnym krokiem, do którego dążył tauren druid. Poproś o pomoc któregoś z tamtejszych druidów.', '', '', '', '', '', '', 0),
(5061, 'koKR', 'Postać morska', '$GUkończyłeś:Ukończyłaś; lekcje, które przechodzą wszyscy młodzi druidzi, zanim przyjmą wodny aspekt. Wróć teraz do swojego nauczyciela, Mathrengyla Niedźwiedziego Kroka, w Darnassus. Pokaż mu swój wisior i udowodnij, że $gjesteś gotów:jesteś gotowa; przyjąć to, czego ma cię nauczyć. On dokończy twoje szkolenie i pozwoli ci stać się jednością z wodą.$B$BŻegnaj, $gmłody druidzie:młoda druidko;. Jeszcze się spotkamy.', 'Wróć do Darnassus i pokaż Mathrengylowi Niedźwiedziemu Krokowi wisior lwa morskiego.', '', '', '', '', '', '', 0),
(5253, 'koKR', 'Kryształ Zin-Malor', 'Imponujące, $N.$B$BKryształu Zin-Malor nie da się już zwrócić świątyni, która, jak wiesz, leży w ruinie. Uważam jednak, że twój trud, by naprawić zło przeszłości, nie powinien pozostać bez nagrody.$B$BOdszukaj arcydruida Fandrala Jeleniorogiego w Darnassus i zanieś mu kryształ, $N. Powinien trafić w ręce tych, którzy nie nadużyją jego mocy. Wygląda na to, że tylko garstka najpotężniejszych władających magią zdołałaby zapanować nad taką siłą.', 'Dostarcz Kryształ Zin-Malor arcydruidowi Fandralowi Jeleniorogiemu w Darnassus.', '', '', '', '', '', '', 0),
(5921, 'koKR', 'Gaj Luny', 'Wszyscy druidzi są mile widziani w świętej krainie Gaju Luny, bez względu na obecne napięcia w Kręgu Cenariona między arcydruidem Jeleniorogim a opiekunem Remulosem, strażnikiem Gaju Luny. Skoro poznajesz już drogę Pazura, nauczę cię czaru, który pozwoli ci się tam przenieść. Rzucaj go zawsze, gdy szukasz wiedzy lub ukojenia Gaju Luny.$B$BNa pierwszą lekcję udaj się do Gaju Luny i porozmawiaj z Dendrite\'em Gwiezdnym Płomieniem w Nocnym Azylu o ścieżce, na którą $gwkroczyłeś:wkroczyłaś;. Powodzenia, $gmłody druidzie:młoda druidko;.', 'Użyj czaru „Teleportacja: Gaj Luny”, aby przenieść się do Gaju Luny. Na miejscu porozmawiaj z Dendrite\'em Gwiezdnym Płomieniem w wiosce Nocny Azyl.', '', '', '', '', '', '', 0),
(5922, 'koKR', 'Gaj Luny', 'Wszyscy druidzi, zarówno taureni, jak i nocne elfy, są mile widziani w świętej krainie Gaju Luny. Opiekun Remulos – strażnik Gaju Luny – czuwa nad wszystkimi druidami, którzy tam zapadają w sen. Skoro poznajesz już drogę Pazura, nauczę cię czaru, który pozwoli ci się tam przenieść. Rzucaj go zawsze, gdy szukasz wiedzy lub ukojenia Gaju Luny.$B$BNa pierwszą lekcję udaj się do Gaju Luny i porozmawiaj z Dendrite\'em Gwiezdnym Płomieniem w Nocnym Azylu o ścieżce, na którą $gwkroczyłeś:wkroczyłaś;. Powodzenia, $gmłody druidzie:młoda druidko;.', 'Użyj czaru „Teleportacja: Gaj Luny”, aby przenieść się do Gaju Luny. Na miejscu porozmawiaj z Dendrite\'em Gwiezdnym Płomieniem w wiosce Nocny Azyl.', '', '', '', '', '', '', 0),
(5931, 'koKR', 'Powrót do Darnassus', 'Nadszedł czas, by nasze drogi się rozeszły, $gmłody druidzie:młoda druidko;, bo stosowanie twoich lekcji prowadzi cię z powrotem do tego, kto cię do mnie przysłał. Mathrengyl Niedźwiedzi Krok naprawdę żyje w równowadze z naturą, choć mieszka niebezpiecznie blisko miejsca, gdzie ta równowaga się zachwiała. Słuchaj jego wskazówek, a wkrótce ukończysz pierwsze lekcje swojej roli obrońcy równowagi.$B$BIdź już, $gmłody druidzie:młoda druidko;. Jeszcze się spotkamy.', 'Wróć do Darnassus i porozmawiaj z Mathrengylem Niedźwiedzim Krokiem w Enklawie Cenariona.', '', '', '', '', '', '', 0),
(6001, 'koKR', 'Ciało i serce', 'Na wschód od Auberdine znajduje się wiele jaskiń lunozwierzy. W tej, która leży najbliżej Auberdine, jest Kamień lunozwierzy. Księżycowy Szpon, obrońca kamienia, stanie z tobą do walki dopiero wtedy, gdy użyjesz na kamieniu cenariońskiego księżycowego pyłu. Księżycowy Szpon skrywa w sobie siłę, którą ty, jako $gjeden:jedna; z Pazura, musisz wykorzystać.$B$B$GZasłużyłeś:Zasłużyłaś; na prawo użycia tego cenariońskiego księżycowego pyłu, $N... teraz pokaż mi, że $gzasłużyłeś:zasłużyłaś; też na siłę ciała i siłę serca, których potrzebuje druid!', 'Użyj cenariońskiego księżycowego pyłu na Kamieniu lunozwierzy w Auberdine, aby przywołać Księżycowego Szpona. Następnie zmierz się z nim i zdobądź siłę ciała i serca, którą w sobie nosi.$B$BGdy skończysz, porozmawiaj z Mathrengylem Niedźwiedzim Krokiem w Darnassus.', 'Zmierz się z Księżycowym Szponem i zdobądź siłę ciała i serca, którą w sobie nosi.', 'Wróć do Mathrengyla Niedźwiedziego Kroka w Enklawie Cenariona w Darnassus.', '', '', '', '', 0),
(6002, 'koKR', 'Ciało i serce', 'Na ziemiach na zachód od Taurajo na Pustkowiach – tuż przed granicą z Mulgorem – leży Kamień lunozwierzy. Lunozwierze to niezwykłe bestie, nie pochodzą z tych stron. Księżycowy Szpon, obrońca kamienia, stanie z tobą do walki, gdy użyjesz na kamieniu cenariońskiego pyłu księżycowego. Księżycowy Szpon skrywa w sobie siłę, którą ty, jako $gjeden:jedna; z Pazura, musisz wykorzystać.$B$B$GZasłużyłeś:Zasłużyłaś; na prawo użycia tego cenariońskiego pyłu księżycowego, $N... teraz pokaż mi, że $gzasłużyłeś:zasłużyłaś; też na siłę ciała i siłę serca, których potrzebuje druid!', 'Użyj cenariońskiego pyłu księżycowego na Kamieniu lunozwierzy między Mulgorem a Pustkowiami, aby przywołać Księżycowego Szpona. Następnie zmierz się z nim i zdobądź siłę ciała i serca, którą w sobie nosi.$B$BGdy skończysz, porozmawiaj z Turakiem Runicznym Totemem w Gromowych Urwiskach.', 'Zmierz się z Księżycowym Szponem i zdobądź siłę ciała i serca, którą w sobie nosi.', 'Wróć do Turaka Runicznego Totemu w Gromowych Urwiskach.', '', '', '', '', 0),
(6121, 'koKR', 'Nowe lekcje', 'Jesteś $ggotów:gotowa; poznać trucizny i władzę, jaką my, druidzi, mamy nad nimi, $N. Cenarius pobłogosławił nas zdolnością oczyszczania nawet z najpodlejszych trucizn za pomocą zwykłej inkantacji. Tego daru nie wolno lekceważyć... i abyś $gprzyswoił:przyswoiła; sobie tę lekcję, będziesz walczyć ze skutkami zatruć tak, jak robiłby to zwykły człowiek bez naszej mocy.$B$BUdaj się do Gaju Luny i porozmawiaj z Dendrite\'em Gwiezdnym Płomieniem. Czeka na ciebie, by rozpocząć lekcję.', 'Udaj się do Gaju Luny i porozmawiaj z Dendrite\'em Gwiezdnym Płomieniem w wiosce Nocny Azyl.', '', '', '', '', '', '', 0),
(6125, 'koKR', 'Władza nad trucizną', '$GPoznałeś:Poznałaś;, co znaczy leczyć zatrucia bez pomocy duchowej mocy. Pamiętaj, co muszą znosić inni w walce z truciznami, gdy wkrótce obejmiesz swoją nową władzę nad nimi.$B$BWróć teraz do Mathrengyla Niedźwiedziego Kroka w Darnassus, $N. Bez wątpienia ma dla ciebie bardzo ważny czar, skoro uczeń zrozumiał daną mu lekcję.$B$BBywaj, $gmłody druidzie:młoda druidko;. Jeszcze porozmawiamy.', 'Wróć do Mathrengyla Niedźwiedziego Kroka w Enklawie Cenariona w Darnassus.', '', '', '', '', '', '', 0),
(6126, 'koKR', 'Nowe lekcje', 'Jesteś $ggotów:gotowa; poznać trucizny i władzę, jaką my, druidzi, mamy nad nimi, $N. Cenarius pobłogosławił nas zdolnością oczyszczania nawet z najpodlejszych trucizn za pomocą zwykłej inkantacji. Tego daru nie wolno lekceważyć... i abyś $gprzyswoił:przyswoiła; sobie tę lekcję, będziesz walczyć ze skutkami zatruć tak, jak robiłby to zwykły człowiek bez naszej mocy.$B$BUdaj się do Gaju Luny i porozmawiaj z Dendrite\'em Gwiezdnym Płomieniem. Czeka na ciebie, by rozpocząć lekcję.', 'Udaj się do Gaju Luny i porozmawiaj z Dendrite\'em Gwiezdnym Płomieniem w wiosce Nocny Azyl.', '', '', '', '', '', '', 0),
(6130, 'koKR', 'Władza nad trucizną', '$GPoznałeś:Poznałaś;, co znaczy leczyć zatrucia bez pomocy duchowej mocy. Pamiętaj, co muszą znosić inni w walce z truciznami, gdy wkrótce obejmiesz swoją nową władzę nad nimi.$B$BWróć teraz do Turaka Runicznego Totemu w Gromowych Urwiskach, $N. Bez wątpienia ma dla ciebie bardzo ważny czar, skoro $guczeń zrozumiał daną mu:uczennica zrozumiała daną jej; lekcję.$B$BBywaj, $gmłody druidzie:młoda druidko;. Jeszcze porozmawiamy.', 'Wróć do Turaka Runicznego Totemu na Wzniesieniu Starszych w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(6561, 'koKR', 'Nikczemność w Czarnych Głębinach', 'Opuściły mnie siły. Potrzebuję twojej pomocy!$b$bDawno temu stała tu wielka świątynia Eluny. Ale nieszczęście doprowadziło ją do ruiny, gdy spaczenie jednego z Przedwiecznych Bogów przesączyło się spod ziemi i skaziło świętą księżycową studnię.$b$bZ wód wynurzył się Aku\'mai, sługa Przedwiecznego.$b$bKultyści Młota Zmierzchu sprzymierzyli się z nagami, by zająć te tereny. Kultyści pod wodzą Kelrisa składają niewinnych w ofierze Aku\'mai, by zyskać moc.$b$bZabij Kelrisa i zanieś jego głowę Bashanie w Gromowych Urwiskach, $N. Proszę.', 'Zanieś głowę Władcy Zmierzchu Kelrisa Bashanie Runicznemu Totemowi w Gromowych Urwiskach.', '', 'Wróć do Bashany Runicznego Totemu na Wzniesieniu Starszych w Gromowych Urwiskach.', '', '', '', '', 0),
(6761, 'koKR', 'Nowe rubieże', 'Wezwaniem Gaju Luny o pomoc zajmie się z mojego polecenia mój zastępca, Mathrengyl Niedźwiedzi Krok. W tej sprawie rozmawiaj z nim – NIE ze mną.$B$BPozwól, że dam ci pewną... przyjacielską... radę. To ja wyprowadziłem nas z ciemności, gdy dla naszej rasy wszystko było stracone – NIE Krąg Cenariona z Gaju Luny. Teldrassil daje nam wszystkim nowe życie! Oni chcieliby, żebyś $guwierzył:uwierzyła; w coś innego, a wiara w ich propagandę byłaby zajęciem dla głupców.$B$B$GSam:Sama; zdecyduj, czy należysz do głupców.', 'Porozmawiaj z Mathrengylem Niedźwiedzim Krokiem w Enklawie Cenariona w Darnassus.', '', '', '', '', '', '', 0),
(6762, 'koKR', 'Rabine Saturna', 'W tej sprawie majordomus opiekuna Remulosa w Gaju Luny, Rabine Saturna, szuka pomocy w badaniu rozległych pustkowi daleko na zachód od Tanaris... a nawet jeszcze dalej na zachód od Un\'Goro. Znajdziesz go w Nocnym Azylu, głównej osadzie Gaju Luny.$B$BTwoja praca bez wątpienia przyniesie nam wszystkim ogromną korzyść, lecz radzę ci stąpać ostrożnie. Między Darnassus a Gajem Luny panują napięcia... które z czasem mogą narastać.', 'Porozmawiaj z Rabine\'em Saturną w wiosce Nocny Azyl w Gaju Luny. Gaj Luny leży między Spaczoną Knieją a Zimozdrojem; prowadzi do niego ścieżka z Warowni Pyskodrzewnych.', '', '', '', '', '', '', 0),
(7671, 'koKR', 'Zamiennik mroźnej szablobestii', '', '', '', 'Wróć do Lelanai na Teldrassilu.', '', '', '', '', 0),
(7672, 'koKR', 'Zamiennik nocnej szablobestii', '', '', '', 'Wróć do Lelanai na Teldrassilu.', '', '', '', '', 0),
(7799, 'koKR', 'Dar tkaniny magów', '', '', '', 'Wróć do Raedona Uderzenia Zmierzchu na Teldrassilu.', '', '', '', '', 0),
(7800, 'koKR', 'Dar runicznej tkaniny', '', '', '', 'Wróć do Raedona Uderzenia Zmierzchu na Teldrassilu.', '', '', '', '', 0),
(7801, 'koKR', 'Więcej runicznej tkaniny', '', '', '', 'Wróć do Raedona Uderzenia Zmierzchu na Teldrassilu.', '', '', '', '', 0),
(8357, 'koKR', 'Taniec za marcepan', 'Choć zbierasz słodycze dla chorego dziecka, i tak musisz pokazać jakąś sztuczkę za smakołyk! Przecież nie możemy zmieniać tradycji, prawda...$B$BMyślę, że cena kawałka marcepanu to w dzisiejszych czasach... TANIEC! Tak jest, pokaż, co potrafisz! Zatańcz dla mnie, a dam ci pyszny marcepan!', 'Użyj emotki tańca przy karczmarce Saelienne, a w zamian otrzymasz marcepan z Darnassus!', '', 'Wróć do karczmarki Saelienne w Darnassus.', 'Zatańcz dla karczmarki Saelienne', '', '', '', 0),
(8360, 'koKR', 'Taniec za marcepan', 'Choć zbierasz słodycze dla chorego dziecka, i tak musisz pokazać jakąś sztuczkę za smakołyk! Przecież nie możemy zmieniać tradycji, prawda...$B$BMyślę, że cena kawałka marcepanu to w dzisiejszych czasach... TANIEC! Tak jest, pokaż, co potrafisz! Zatańcz dla mnie, a dam ci pyszny marcepan!', 'Użyj emotki tańca przy karczmarce Pali, a w zamian otrzymasz marcepan z Gromowych Urwisk!', '', 'Wróć do karczmarki Pali w Gromowych Urwiskach.', 'Zatańcz dla karczmarki Pali', '', '', '', 0),
(8718, 'koKR', 'Nestor Chyże Ostrze', '', '', '', '', '', '', '', '', 0),
(8733, 'koKR', 'Eranikus, tyran Snu', 'To podróż ku odkupieniu, bohaterze. Gdybym dziś zginął, umarłbym w słusznej i sprawiedliwej sprawie. Musisz odzyskać zielony odłamek berła. Musisz oczyścić Eranikusa ze skazy, którą naznaczyli go Przedwieczni.$B$BUdaj się do Darnassus. Tuż za murami miasta znajdziesz jednego z moich wysłanników. Wprawi on sprawy w ruch i powiadomi Tyrande o naszych planach, nie alarmując Jeleniorogiego.$B$B<Malfurion wzdycha.>$B$BUpadek, który dojrzewał przez tysiąc lat...', 'Udaj się na Teldrassil i odszukaj wysłannika Malfuriona gdzieś za murami Darnassus.$B', '', '', '', '', '', '', 0),
(8836, 'koKR', 'Jeden sygnet pochwalny', '', '', '', 'Wróć do oficera Maloofa w Kniei Elwynn.', '', '', '', '', 0),
(8837, 'koKR', 'Dziesięć sygnetów pochwalnych', '', '', '', 'Wróć do oficera Maloofa w Kniei Elwynn.', '', '', '', '', 0),
(9262, 'koKR', 'Zbadaj Plagę pod Darnassus', 'Król Lisz nasłał nieumarłych pod same nasze drzwi; nie możemy stać bezczynnie! Z pewnością staniesz w obronie Darnassus przed tymi przeklętymi najeźdźcami? $b $bNa zewnątrz widać dziwne runiczne kręgi, jaśniejące tą samą energią, która otacza nieumarłych i nekropolię w górze. Na pewno mają jakieś znaczenie i chcę, żebyś $gdowiedział:dowiedziała; się jakie. Przy okazji przetrzeb szeregi tych potworności; przynieś mi dowód ich śmierci razem z tym, co ustalisz, a wynagrodzę cię. Ruszaj!', 'Zdobądź trzy przygasłe nekrotyczne kamienie od sług Plagi pod Darnassus i zbadaj jaśniejące runiczne kręgi w pobliżu ich obozu.', 'Zbadaj krąg', 'Wróć do porucznik Beithy przy Sadzawkach Arlithrien na Teldrassilu.', '', '', '', '', 0),
(9432, 'koKR', 'Podróż do Astranaar', 'Cieszę się, że $gprzybyłeś:przybyłaś; pomóc. Właściwie jest coś, co możesz zrobić.$B$BW ramach naszego przystąpienia do Przymierza chciałabym, żebyś $gudał:udała; się do Astranaar, osady nocnych elfów. Leży w Jesionowej Kniei, wielkim lesie na południe od Mrocznego Wybrzeża, na kontynencie Kalimdor.$B$BGdy dotrzesz na miejsce, porozmawiaj z Obrończynią Palanaar i dowiedz się, czy możesz jakoś pomóc mieszkańcom.', 'Udaj się do Astranaar w Jesionowej Kniei i porozmawiaj z Obrończynią Palanaar.', '', '', '', '', '', '', 0),
(10352, 'koKR', 'Dar wełnianego płótna', '', '', '', 'Wróć do Raedona Uderzenia Zmierzchu na Teldrassilu.', '', '', '', '', 0),
(10354, 'koKR', 'Dar jedwabnego płótna', '', '', '', 'Wróć do Raedona Uderzenia Zmierzchu na Teldrassilu.', '', '', '', '', 0),
(12773, 'koKR', 'Darnassus', 'Nasze modlitwy zostały wysłuchane! Dzięki skupieniu Światłości od naaru z Shattrath i wspólnym błogosławieństwom wiernych stworzyliśmy święte artefakty o wielkiej mocy. Te artefakty będą naszą bronią przeciw knowaniom Króla Lisza.$B$BWeź go, $n. Strzeż go pilnie i bezpiecznie dostarcz do Darnassus. Oddaj go Tyrande Szept Wiatru – jej kapłanki znajdą w nim cenne źródło mocy w walce z bezbożnymi siłami z Północy.', 'Biskup Lazaril chce, żebyś $gzaniósł:zaniosła; artefakt nasycony Światłością Tyrande Szept Wiatru w Darnassus.', '', 'Wróć do Tyrande Szept Wiatru w Ogrodach Świątynnych w Darnassus.', '', '', '', '', 0),
(14054, 'koKR', 'Łatwe jak placek', 'Isaac ciężko pracuje, pomagając biesiadnikom poznać tradycyjną ucztę na Dary Pielgrzymów i nauczyć się przyrządzania potraw ze wszystkich składników, które zbieramy o tej porze roku. Staram się, żeby na stołach nie brakowało żadnej z potraw, ale kończy nam się jeden z przysmaków Isaaca – placek dyniowy.$B$BMożesz zdobyć dla nas trochę? Jeśli chcesz $gsam:sama; upiec placki, musisz kupić dojrzałe dynie z Elwynn u sprzedawcy Darów Pielgrzymów pod Wichrogrodem.', 'Przynieś 20 kawałków placka dyniowego Mary Allerton na miejsce uczty w pobliżu bram Darnassus.', '', 'Wróć do Mary Allerton na Tarasie Wojowników w Darnassus.', '', '', '', '', 0),
(14060, 'koKR', 'Łatwe jak placek', 'Dokin i Laha ciężko pracują, pomagając biesiadnikom poznać tradycyjną ucztę na Dary Pielgrzymów i nauczyć się przyrządzania potraw ze wszystkich składników, które zbieramy o tej porze roku. Staram się, żeby na stołach nie brakowało żadnej z potraw, ale kończy nam się placek dyniowy.$B$BMożesz zdobyć dla nas trochę? Jeśli chcesz $gsam:sama; upiec placki, musisz kupić dojrzałe dynie z Tirisfal u sprzedawcy Darów Pielgrzymów pod Podmiastem.', 'Przynieś 20 kawałków placka dyniowego Maharze Złotej Pszenicy na miejsce uczty pod Gromowymi Urwiskami.', '', 'Wróć do Mahary Złotej Pszenicy w Mulgorze.', '', '', '', '', 0),
(14085, 'koKR', 'Naucz się jeździć w Darnassus', 'Tę broszurę reklamującą naukę jazdy wierzchem i sprzedaż wierzchowców przysłał Jartsam.$B$BJartsama znajdziesz w Enklawie Cenariona w Darnassus.', 'Oddaj broszurę Jartsamowi w Enklawie Cenariona w Darnassus.', '', 'Wróć do Jartsama na Tarasie Kupców w Darnassus.', '', '', '', '', 0),
(14170, 'koKR', 'Wdzięczni umarli', 'Dobrze znów odwiedzić przyjaciół i rodzinę, choć chyba trochę przesadziłam... Zjadłam już wszystko, co dla mnie przygotowali!$B$BCzy mogę cię prosić o jeszcze trochę tego pysznego chleba umarłych? Będę bardzo wdzięczna...$B$BPrzepis sprzedaje chyba tamten Chapman.', 'Zdobądź chleb umarłych i daj go radosnemu duchowi nocnego elfa na cmentarzu w Darnassus.$B$BUżyj pomarańczowej aksamitki, aby zobaczyć niewidzialnego na co dzień ducha.', '', 'Wróć do radosnego ducha nocnego elfa przy Sadzawkach Arlithrien na Teldrassilu.', '', '', '', '', 0),
(14409, 'koKR', 'Ostrożny powrót', 'Chwila twojego czasu, $N.$b$bNadchodzą zmiany. To one wywiodły nas z ruin Eldre\'Thalas i znów wypuściły w szeroki świat. Przybyłem tu, by badać to miasto, i nie mogę się stąd oddalać, ale jeśli zechcesz, mam dla ciebie zadanie.$b$bMój towarzysz wyruszył do Darnassus, by porozmawiać z tamtejszą Wielką Kapłanką, abyśmy mogli dojść do porozumienia. Zanieś ten dziennik Mordentowi Równemu Cieniowi w świątyni. Może mu pomóc w jego dyplomatycznej misji.', 'Zanieś dziennik Darosa Mordentowi Równemu Cieniowi w Darnassus.', '', 'Wróć do arcymaga Mordenta Równego Cienia w Ogrodach Świątynnych w Darnassus.', '', '', '', '', 0),
(24610, 'koKR', 'Prezent dla Wielkiej Kapłanki Eluny', 'Chcesz zrobić uroczą bransoletkę z talizmanami dla Wielkiej Kapłanki Eluny? Na pewno byłaby zachwycona.$B$BMasz już zestaw kolekcjonera uroczych talizmanów?', 'Wręcz uroczą bransoletkę z talizmanami Tyrande Szept Wiatru w Darnassus.', '', 'Wróć do Tyrande Szept Wiatru w Ogrodach Świątynnych w Darnassus.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(26, 'koKR', 'Witaj, $N. Nadszedł czas, byś $gpoznał:poznała; naszą postać morską. Pozwala ona swobodnie i bez końca poruszać się w wodzie. Ten aspekt okaże się dla ciebie przydatnym narzędziem i błogosławieństwem... ale trzeba na niego zasłużyć, zanim się go opanuje.$B$BCzekają cię dwie próby. Pierwsza sprawdzi, jak radzisz sobie w wodzie pod presją. Druga sprawdzi twoją determinację w zgłębianiu istoty samej postaci.$B$BBądź $ggotów:gotowa;, bo czas próby właśnie nadszedł.', 0),
(27, 'koKR', 'Witaj, $N. Nadszedł czas, byś $gpoznał:poznała; naszą postać morską. Pozwala ona swobodnie i bez końca poruszać się w wodzie. Ten aspekt okaże się dla ciebie przydatnym narzędziem i błogosławieństwem... ale trzeba na niego zasłużyć, zanim się go opanuje.$B$BCzekają cię dwie próby. Pierwsza sprawdzi, jak radzisz sobie w wodzie pod presją. Druga sprawdzi twoją determinację w zgłębianiu istoty samej postaci.$B$BBądź $ggotów:gotowa;, bo czas próby właśnie nadszedł.', 0),
(162, 'koKR', 'Ten raport... My, nocne elfy, znamy grozę, o której tu mowa. Fizzledowser mądrze zrobił, przysyłając do mnie ten raport i ciebie.$B$BTe stworzenia szybko pochłoną pustynię Tanaris. To jedno z największych zagrożeń, z jakimi kiedykolwiek przyjdzie nam się zmierzyć. Zapamiętaj tę nazwę, $N: silithidy. Owady opisane w raporcie to silithidy, narzędzia jednego z największych zagrożeń, przed którymi stoją zarówno Horda, jak i Przymierze.$B$BGdybyśmy tylko wcześniej mieli dość rozumu, by to dostrzec.', 0),
(730, 'koKR', 'Tak się cieszę, że główny archeolog Siwowąs po nas posłał...', 0),
(741, 'koKR', 'Ojej! Tylko poszukiwacz Remtravel mógł dokonać takiego znaleziska!', 0),
(942, 'koKR', 'Ojej! Mówisz, że to pochodzi z dalekich ziem Kalimdoru?$B$BNiesamowite! Po prostu niesamowite!', 0),
(952, 'koKR', 'Ach. Dziękuję, $N. Dziwne to jednak. Arcydruid zawsze wydaje się tak bardzo spieszyć. Las wie, że wszystko stanie się w wyznaczonym czasie. Shan\'do Burzogniewny to rozumiał.', 0),
(1037, 'koKR', 'Velinde Gwiezdna Pieśń? To, że kapłanka zniknęła jakiś czas temu, jest niemal na pewno powszechnie wiadome. Co do dalszych szczegółów okoliczności jej odejścia... musiałabym mieć dobry powód, by zdradzić takie informacje.', 0),
(1038, 'koKR', 'Wygląda na to, że zniknięcie Velinde jest bardziej niepokojące, niż początkowo się wydawało. Mimo to nie mogę uwierzyć, że spotkał ją zły koniec. Może warto byłoby się z nią skontaktować.$B$B$N, skoro tak żywo interesujesz się tą sprawą, chciałabym prosić cię o pomoc.', 0),
(1039, 'koKR', 'Ktoś z twojego ludu, co? Przyznam, że rzadko tu takich widujemy. Kogoś szukasz, tak? Daj mi chwilę, na pewno mam to zapisane w którejś z ksiąg.$B$BWielu ludzi się tędy przewija, więc daj mi chwilkę.', 0),
(1044, 'koKR', 'A więc taki los spotkał Velinde? Wielka Kapłanka zmartwi się, słysząc o tym – przed jej zniknięciem były dobrymi przyjaciółkami. Kosa Eluny z pewnością została jej dana przez naszą boginię jako łaska i niepokoi mnie, że wymknęła się z rąk jej sług.$B$BTo jednak sprawa na inny czas. Zawdzięczam ci niemało za to, czego $gdokonałeś:dokonałaś;.', 0),
(1081, 'koKR', 'Witaj, $N. Istotnie, słyszałam już twoje imię i choć wciąż jesteś $gmłody:młoda;, cieszy mnie ścieżka, którą $gobrałeś:obrałaś;.$B$BWyświadczysz mi wielki zaszczyt, jeśli przyjmiesz to w dowód uznania.', 0),
(1142, 'koKR', 'Nie!$B$BTo niesprawiedliwe. O, okrutny i nieznośny świecie!$B$BMuszę teraz dźwigać ten ciężar żałoby i nie pozwolić, by dzieło Heralatha umarło razem z nim.$B$B$GWykazałeś:Wykazałaś; się odwagą, wracając z tak niebezpiecznego miejsca, $N. Ale proszę, zostaw mnie teraz.$B$BBędę opłakiwać go w samotności.', 0),
(1198, 'koKR', 'Strażnik Brzasku Shaedlass dobrze zrobił, przysyłając cię tutaj. W tym splugawionym miejscu rzeczywiście knuje się nikczemny spisek.', 0),
(1199, 'koKR', 'Bez wątpienia płynie w tobie dzielna i szlachetna krew, $N. Argentowy Brzask wyraża uznanie dla twoich starań w walce ze złem.', 0),
(1200, 'koKR', 'Kelris długo nam się wymykał.$B$BWygląda na to, że ilekroć zło dawało o sobie znać w tych stronach, Kelris maczał w tym palce. Przez pewien czas uważaliśmy go za zmarłego albo zaginionego.$B$BAle teraz wszystko nabiera sensu. Kładąc kres jego panowaniu, $gocaliłeś:ocaliłaś; życie wielu niewinnych.$B$BNa Światłość! Składać kogoś w ofierze słudze Przedwiecznego dla własnej korzyści – to czyn ponad wszelką naganę!$B$B$GDokonałeś:Dokonałaś; wielkiego czynu, $N. Pozdrawiam cię w imieniu Argentowego Brzasku.', 0),
(1582, 'koKR', 'Tak, to dobre wyroby. Masz wprawną rękę i oko do szczegółów. Czeka cię obiecująca przyszłość w garbarstwie.$B$BProszę, $N. Pokażę ci wykrój na kamizelkę księżycowej poświaty.', 0),
(1683, 'koKR', 'Dobra robota, $N. Dobrze wiedzieć, że Vorlus został pokonany, a nasza księżycowa studnia oczyszczona. Dobrze też widzieć młodych wojowników, którym zależy na tym, by nasz umiłowany Teldrassil pozostał wolny od skażenia.$B$BA teraz zacznijmy twoje szkolenie...', 0),
(1686, 'koKR', 'Dzielnie się $gspisałeś:spisałaś;, $N.$B$B$GDałeś:Dałaś; Cieniowi Elury zasłużony spokój, a z zebranego elunitu wykujemy dla ciebie przednią broń.', 0),
(1692, 'koKR', 'Ach, ruda elunitu. To wspaniały metal do obróbki, bo pobłogosławiła go sama bogini Elune. Wykuwanie z niego broni będzie dla mnie zaszczytem.$B$BZaczekaj, proszę, aż skończę pracę...', 0),
(1693, 'koKR', '$N, wykułem tę broń z elunitu, który mi $gprzyniosłeś:przyniosłaś;. Proszę, weź tę, która najbardziej ci odpowiada.$B$BI muszę ci podziękować. Praca z elunitem to zarazem zaszczyt i przyjemność.', 0),
(1710, 'koKR', 'Ach, dziękuję. Świetnie się nadadzą!$B$BZaraz zabieram się do wykonania zbroi...', 0),
(1711, 'koKR', 'Skończyłem twoją część zbroi i jestem z niej bardzo zadowolony. Nowe techniki Furena doskonale połączyły się z moimi i jestem pewien, że ta zbroja okaże się niezwykle wytrzymała.$B$BDziękuję, $N. Niech dobrze ci służy w przyszłych bitwach.', 0),
(2242, 'koKR', 'To ponure wieści, $N. Wygląda na to, że choroba, która dotknęła lasy i rzeki Mrocznego Wybrzeża, zaczęła skażać także nasz dom.$B$BDobrze nam $gsłużyłeś:służyłaś;, ale nic więcej nie możesz tu zdziałać. Weź to ostrze w nagrodę za służbę Teldrassilowi.', 0),
(2518, 'koKR', 'Las opłakuje lady Sathrah, ale to musiało się stać.$B$BDziękuję, $N.', 0),
(2519, 'koKR', 'A więc przysłała cię siostra Aquinne?', 0),
(2520, 'koKR', 'Strata lady Sathrah napawa smutkiem, ale tylko w ten sposób może się ona odrodzić z odnowionym duchem.$b$bNiech Elune łaskawie przyjmie ofiarę, którą jej $gzłożyłeś:złożyłaś;.', 0),
(2853, 'koKR', 'Ach tak, przysłał cię Pratt. Choć jest człowiekiem, czasem przypomina mi nas, nocne elfy. Jego oddanie i talent do obróbki skóry robią wrażenie. Skoro w tym liście tak cię chwali, to jest to oznaka szacunku, którą uznaję.$B$BWiem, że nauczył cię sztuki dzikiej skóry. Pozwól, że dokończę twoje szkolenie tym wykrojem. Zrób z niego dobry użytek; niewielu na świecie zna tajniki płaszczy z dzikiej skóry.', 0),
(2972, 'koKR', 'To niezwykła historia, $N. Cieszy nas, że $gpomogłeś:pomogłaś; nie tylko smoczemu rodowi, lecz także jednej z naszych kapłanek. Jer\'kai dobrze zrobiła, przysyłając cię do mnie. Dopilnuję, by sygnet do niej wrócił – niedługo wysyłam zwiadowców w stronę Feralas. Będzie to dla nich jeszcze jedna sprawa do zbadania podczas misji.$B$BJeszcze raz dziękuję i proszę, czuj się tu jak u siebie.', 0),
(3370, 'koKR', 'Przysłała cię Falla? No cóż, zobaczmy ten odłamek, o którym, jak mówisz, tak niechętnie mówiła...$B$B<Mathrengyl wpatruje się w odłamek>$B$BOch... Nie... No cóż.$B$B$N, dziękuję, że mi to $gprzyniosłeś:przyniosłaś;. Radzę ci jednak nie rozprawiać o takich sprawach. Tymi kwestiami muszą zająć się wyłącznie druidzi Kręgu Cenariona.$B$BPowiedzmy tylko, że w Szmaragdowym Śnie dzieje się inaczej, niż sądziliśmy...$B$BByć może w przyszłości nasze ścieżki znów się skrzyżują.', 0),
(3378, 'koKR', 'Elune uśmiecha się do ciebie tego wieczoru, $N. $GZwróciłeś:Zwróciłaś; jej zagubioną duszę. Przyjmij, proszę, to w dowód naszej wdzięczności.', 0),
(3764, 'koKR', 'Złóż tu swój cenny ładunek, $N. To musiało być nie lada brzemię... podobne do tego, które ja dźwigam jako wizjoner. Oto honorarium za twoją pracę, zgodnie z poleceniem samego arcydruida.$B$BArcydruid Jeleniorogi chce znów z tobą porozmawiać, $N, ale przy jego kolejnym zadaniu przyda ci się ziołozbieractwo na poziomie czeladnika. Jeśli jednak go nie znasz, nadal możesz pomóc Kręgowi!', 0),
(3781, 'koKR', 'Tak, ten bon jest ważny na dwadzieścia paczek nasion. Jeśli ci się skończą, możemy zapewnić więcej. Niestety, wytwarzanie nasion tharlendris w większych ilościach jest dość kosztowne. Dlatego Krąg Cenariona prosi tych, którzy nam pomagają, by pokryli część kosztów.$B$BCi, którzy wracają z jutroziarnem, przekonują się, że nagroda od arcydruida z nawiązką wynagradza ten wydatek.', 0),
(3782, 'koKR', 'Tak, ten bon jest ważny na dwadzieścia paczek nasion. Jeśli ci się skończą, możemy zapewnić więcej. Niestety, wytwarzanie nasion tharlendris w większych ilościach jest dość kosztowne. Dlatego Krąg Cenariona prosi tych, którzy nam pomagają, by pokryli część kosztów.$B$BCi, którzy wracają z jutroziarnem, przekonują się, że nagroda od arcydruida z nawiązką wynagradza ten wydatek.', 0),
(3785, 'koKR', 'Dobra robota, $N. Na pewno przekażę je samemu arcydruidowi, gdy będzie ich potrzebował. Tymczasem przyjmij to, proszę, w dowód wdzięczności Kręgu Cenariona.$b$bNa razie nieustannie potrzebujemy jutroziarna; jeśli chcesz nadal nam pomagać, wróć, gdy wyhodujesz go więcej.', 0),
(3803, 'koKR', 'Doskonale – to jutroziarno z pewnością ucieszy arcydruida. Muszę jednak przyznać... że sama jego bliskość budzi we mnie lekki niepokój. Mogę sobie tylko wyobrazić, jak trudno arcydruidowi znosić je w tak dużych ilościach!$B$BTo dla ciebie, $N. Krąg Cenariona dziękuje ci za nieustające wsparcie.', 0),
(4267, 'koKR', 'My, nocne elfy, znamy grozę opisaną w tym raporcie. Shandris mądrze zrobiła, przysyłając do mnie ten raport i ciebie.$B$BTe stworzenia szybko pochłoną Feralas. To jedno z największych zagrożeń, z jakimi kiedykolwiek przyjdzie nam się zmierzyć. Owady, które ty i posłaniec napotkaliście, to silithidy. Są jedynie narzędziami jednego z największych zagrożeń, przed jakimi kiedykolwiek staną Horda i Przymierze.$B$BModlę się, byśmy mieli dość determinacji, by je pokonać, zanim one zniszczą nas.', 0),
(4493, 'koKR', 'Tak, domyśliłem się, że przysłała cię Gracina. Twoje doświadczenie w walce z tymi stworami jest bezcenne; o ile wiem, nikt wcześniej nie miał do czynienia z ich rodzajem. Co do pomysłu Graciny, że Krater Un\'Goro jest ich sercem... może i tak jest. Un\'Goro to tajemnicza i niebezpieczna dżungla na zachód stąd. Może to także krok bliżej do zrozumienia, o co chodzi z tymi silithidami.', 0),
(4508, 'koKR', 'Naprawdę to doceniam, ale nie jestem pewna, na ile nam to pomoże. Przymierze lekceważy zagrożenia z każdej strony poza Hordą, a nawet nasi przywódcy tu, w Darnassus, nie potrafią się zgodzić, czym właściwie jest to zagrożenie. Głupcy tacy jak Fandral Jeleniorogi twierdzą, że silithidy w niczym nie przypominają zagrożenia z zamierzchłej przeszłości, za jakie je uważam. Jego ignorancję przewyższa tylko jego arogancja.$B$B$GWidziałeś:Widziałaś; to zagrożenie na własne oczy, $N. Musimy wytrwać w walce z silithidami!', 0),
(4510, 'koKR', 'Ten bon bankowy upoważnia mnie do wydania przedmiotu z konta Graciny Mocy Ducha i przekazania go tobie. Chyba należą się gratulacje!', 0),
(4986, 'koKR', 'To... to bardzo dziwne. Ten druid – i to tauren – powierzył ci mnóstwo cennych informacji o zasięgu zarazy Plagi. Dziwi mnie, że tauren przekazał takie informacje komuś z Przymierza, i to dobrowolnie, jeśli to, co mówisz, jest prawdą. Obiecuję ci, że zrobimy z tego dobry użytek. Może taureni nie odeszli od Cenariusa tak daleko, jak sądzi Fandral...$B$BEkhm, w każdym razie – przyjmij to, proszę, w podzięce od Kręgu Cenariona.', 0),
(5061, 'koKR', 'Imponujące, $N. Jesteś $ggotów:gotowa; poznać postać morską i z przyjemnością cię jej nauczę.$B$BW uznaniu twoich osiągnięć w obu próbach daję ci też ten przedmiot. Mam nadzieję, że okaże się cennym uzupełnieniem ekwipunku obrońcy natury i strażnika równowagi.', 0),
(5253, 'koKR', 'Słyszałem o Krysztale Zin-Malor. Ten, kto się nim posługuje, zyskuje niewiarygodną moc arkanów, lecz tylko wtedy, gdy jest jej naprawdę godzien. Imponuje mi, że nie tylko $godzyskałeś:odzyskałaś; kryształ, ale też znasz własne granice i nie $gpróbowałeś:próbowałaś; użyć go $gsam:sama;.$B$BDziękuję, że mi go $gprzyniosłeś:przyniosłaś;, $N. Będziemy go strzec, a przeklęte duchy, które niegdyś strzegły roztrzaskanego kryształu, niech wreszcie zaznają spokoju.', 0),
(5921, 'koKR', '„I tak się zaczyna, Ojcze Cenariusie. I tak się zaczyna”.$B$BDendrite kreśli nad sobą szybki, niewidzialny gest. Otacza go lekka aura mocy.$B$B„Pierwszym spojrzeniem natury, które musisz przyswoić, jest spojrzenie niedźwiedzia. Wprowadzę cię na ścieżkę zrozumienia tego aspektu druidzkiego życia, ale to ty musisz go przyjąć i nieść dalej – teraz i na zawsze!”', 0),
(5922, 'koKR', '„I tak się zaczyna, Ojcze Cenariusie. I tak się zaczyna”.$B$BDendrite kreśli nad sobą szybki, niewidzialny gest. Otacza go lekka aura mocy.$B$B„Pierwszym spojrzeniem natury, które musisz przyswoić, jest spojrzenie niedźwiedzia. Wprowadzę cię na ścieżkę zrozumienia tego aspektu druidzkiego życia, ale to ty musisz go przyjąć i nieść dalej – teraz i na zawsze!”', 0),
(5931, 'koKR', 'Witaj z powrotem, $N. Czuję, że twoje pierwsze spotkanie z Wielkim Duchem Niedźwiedzia wyglądało tak samo jak u wszystkich druidów, którzy wkraczają na ścieżkę Pazura... było nieco oszałamiające, ale bardzo intensywne. Wiem, że ze mną było tak samo.$B$BWielki Duch Niedźwiedzia jest częścią Azeroth, odkąd Azeroth istnieje na niebiosach. Polegamy na jego mądrości i jego mocy, które podsycają nasze powołanie. Nadszedł czas na twoją pierwszą próbę tego powołania. Słuchaj uważnie...', 0),
(6001, 'koKR', '$GZrobiłeś:Zrobiłaś; wreszcie wielki krok w o wiele większy świat, $N. Wyczuwam w tobie nauki Wielkiego Ducha Niedźwiedzia i czuję, że $gotrzymałeś:otrzymałaś; siłę, którą nosił w sobie Księżycowy Szpon.$B$BNa twojej drodze nie ma już przeszkód... pozwól, że teraz nauczę cię, co znaczy być druidem Pazura!', 0),
(6002, 'koKR', '$GZrobiłeś:Zrobiłaś; wreszcie wielki krok w o wiele większy świat, $N. Wyczuwam w tobie nauki Wielkiego Ducha Niedźwiedzia i czuję, że $gotrzymałeś:otrzymałaś; siłę, którą nosił w sobie Księżycowy Szpon.$B$BNa twojej drodze nie ma już przeszkód... pozwól, że teraz nauczę cię, co znaczy być druidem Pazura!', 0),
(6121, 'koKR', 'Witaj, $gmłody druidzie:młoda druidko;. Cieszę się, że jesteś $ggotów:gotowa; i $gchętny:chętna;, by nauczyć się leczenia zatruć.$B$BDawniej większość druidów przechodziła zaplanowane z góry próby, lecz twoja praca nie będzie niczym takim. W Auberdine doszło do fali zatruć zwierząt, a tamtejsza osada nie potrafi sobie z nią poradzić. Dlatego jej przedstawiciel poprosił Gaj Luny o pomoc, a my wysyłamy tam ciebie. To nie ćwiczenie – twoja praca będzie jak najbardziej prawdziwa. Pamiętaj o tym.', 0),
(6125, 'koKR', 'Witaj z powrotem. Od twojego odejścia śledziłem postępy w tej lekcji i muszę przyznać, że zaskoczyło mnie to, co dzieje się w Auberdine. Trzeba to będzie dokładniej zbadać, bo wprowadzanie takich trucizn do środowiska bardzo zaburza równowagę.$B$BW trudnej sytuacji $gzachowałeś:zachowałaś; spokój i godność. Nie znajduję lepszej nagrody niż trwała władza nad trucizną. Korzystaj z niej dobrze, $N... korzystaj dobrze.', 0),
(6761, 'koKR', 'Tak, $N, dziękuję, że $gprzyszedłeś:przyszłaś;. Przepraszam za to nieporozumienie... między tutejszym arcydruidem a opiekunem Remulosem z Gaju Luny panuje gęsta atmosfera nieufności. Każdy podejrzewa drugiego o krętactwo, a to, że dziwne skażenia Teldrassilu wciąż się szerzą, pozostaje tu palącym problemem. Nie pomaga to rozwiać podejrzeń.$B$BTak czy inaczej, nasz obowiązek wobec Kręgu Cenariona pozostaje... nawet jeśli ci, którzy nim przewodzą, nie są ze sobą zgodni.', 0),
(6762, 'koKR', 'Jestem Rabine Saturna i w imieniu opiekuna Remulosa oraz wszystkich mieszkańców tej świętej polany witam cię.$B$BDoceniam twoje zainteresowanie i gotowość, by pomóc Kręgowi Cenariona. Wiem też, że arcydruid z Darnassus okazał ci niezadowolenie z tego, że nam pomagasz. Bądź $gpewny:pewna;, że służy to większemu dobru i że nie grożą ci żadne nieprzemyślane konsekwencje, które mogłyby cię spotkać.$B$BJesteś tu wśród przyjaciół, $N.', 0),
(8357, 'koKR', 'Ale z ciebie taneczna maszyna, $N!$B$BOto twój smakołyk za to, że tak dzielnie $gdałeś:dałaś; się namówić. Wesołych Zaduszników i pozdrów ode mnie swojego chorego małego przyjaciela! Mam nadzieję, że szybko wyzdrowieje.', 0),
(8360, 'koKR', 'Ale z ciebie taneczna maszyna, $N!$B$BOto twój smakołyk za to, że tak dzielnie $gdałeś:dałaś; się namówić. Wesołych Zaduszników i pozdrów ode mnie swojego chorego małego przyjaciela! Mam nadzieję, że szybko wyzdrowieje.', 0),
(8713, 'koKR', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8716, 'koKR', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8717, 'koKR', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8718, 'koKR', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8720, 'koKR', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8721, 'koKR', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8723, 'koKR', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8724, 'koKR', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8725, 'koKR', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8726, 'koKR', 'Niebiosa w swych niezliczonych gwiazdach kryją odpowiedzi na ziemskie tajemnice, $N. Czyż więc mądrzy i ci, którym sprzyja szczęście, nie mogliby spojrzeć w górę i odnaleźć prawdy?', 0),
(8733, 'koKR', 'Ognik milczy, słychać tylko niskie buczenie. Co dziwne, potrafi porozumiewać się z tobą myślami.', 0),
(9432, 'koKR', 'Zawsze miło zobaczyć choć trochę znajomą twarz. Ty zapewne jesteś $N. Emisariuszka Valustraa uprzedziła mnie, że się zjawisz.$B$BMieszkańcy Jesionowej Kniei potrzebują naszej pomocy, $N. Porozmawiaj z mieszkańcami Astranaar i sprawdź, jak możesz im pomóc.', 0),
(12773, 'koKR', 'Cóż to? Cóż za dar! Zamknęli w tym artefakcie tyle Światłości, że lśni niemal jak księżyc! Nasze kapłanki skierują tę moc przeciw naszym wrogom, a najazd Króla Lisza z pewnością się nie powiedzie. Dziękuję, $N. Nasze drzewo świata będzie bezpieczne.$b$bCo więcej, wyczuwamy, że daleko na północy, ukryte w pobliżu samych włości Króla Lisza, może rosnąć jeszcze jedno drzewo świata. Być może kiedyś... otoczymy opieką oba drzewa i zwiastujemy nową erę pokoju.', 0),
(14054, 'koKR', 'Są idealne. Isaac i wszyscy inni będą zachwyceni!', 0),
(14409, 'koKR', 'Ach, zapiski Darosa. Zawsze skrupulatnie odnotowywał postępy. Jego słowa mogą pomóc wyjaśnić, jak daleko zaszliśmy.$b$bDziękuję, że mi to $gprzyniosłeś:przyniosłaś;. Być może będziemy się częściej widywać, gdy wszyscy zrozumieją, że nie mamy złych zamiarów.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(162, 'koKR', 'Pokój i spokój niech będą z tobą, $gnieznajomy:nieznajoma;. Czemu mnie dziś $gszukałeś:szukałaś;?', 0),
(741, 'koKR', 'Co mogę dla ciebie zrobić?', 0),
(942, 'koKR', 'Co tam masz, przyjacielu?', 0),
(952, 'koKR', 'Ach. $N. W czym Onu może ci pomóc?', 0),
(1038, 'koKR', 'Czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(1142, 'koKR', 'Co cię sprowadza do mojego domu?', 0),
(1199, 'koKR', 'Czarne Głębiny były niegdyś pradawną świątynią nocnych elfów. Mieściła się w niej niezwykle potężna księżycowa studnia. Kto wie, jakie zło warzy się tam teraz z rąk Młota Zmierzchu.$B$BCzy $gzdołałeś:zdołałaś; choć trochę ich stamtąd przegnać?', 0),
(1200, 'koKR', 'Czas to cenne dobro, $N.$B$BMoim zadaniem tu, w Darnassus, jest dbać o to, by Argentowy Brzask rósł w siłę, a złe moce wdzierające się do Kalimdoru zostały powstrzymane.$B$BMów szybko, z czym przychodzisz, albo ruszaj w swoją drogę.', 0),
(1582, 'koKR', 'Witaj, $N.', 0),
(1683, 'koKR', 'Masz róg, $N? Czy nasza księżycowa studnia jest wolna od tego pomiota Vorlusa?', 0),
(1686, 'koKR', '$GPokonałeś:Pokonałaś; Cień Elury, $N? I czy masz zaginioną rudę elunitu?', 0),
(1692, 'koKR', 'Witaj, $N. Jak mogą ci się przysłużyć moje umiejętności?', 0),
(1710, 'koKR', 'Masz skorupy, $N? Są bardzo wytrzymałe i można z nich przygotować lakier, którym pokryję ogniwa mojej nowej kolczugi.', 0),
(2242, 'koKR', 'Masz coś do zameldowania w sprawie Sethira Pradawnego, $N?', 0),
(2518, 'koKR', 'Żałuję, że musiałam powierzyć ci to zadanie, ale dla lady Sathrah nie ma już nadziei.$B$BPragniemy złożyć kądziołki w ofierze Elunie. Dzięki tej ofierze Elune pobłogosławi Sathrah, by mogła się odrodzić i zaznać spokoju.', 0),
(2520, 'koKR', 'Czy $gzłożyłeś:złożyłaś; ofiarę przy fontannie, $n?', 0),
(2853, 'koKR', 'Witaj... Po twoim obliczu poznaję, że jesteś $ggarbarzem:garbarką;, tak jak ja. Przychodzisz czerpać z moich umiejętności, a może masz do mnie inną sprawę?', 0),
(2972, 'koKR', 'Witaj, dziecko. Cieszy nas, że do świątyni przybywa coraz więcej potężnych poszukiwaczy przygód. Jeśli znajdziesz czas, czy opowiesz jedną czy dwie historie młodszym poszukiwaczom przygód? Wiem, że wielu z nich skorzystałoby na twojej mądrości.$B$BWybacz, cóż za nieuprzejmość z mojej strony. $GPrzyszedłeś:Przyszłaś; do świątyni po naszą pomoc, a ja cię obarczam. Proszę, wybacz mi. Powiedz, co słudzy Światłości mogą dla ciebie zrobić.', 0),
(3369, 'koKR', 'W czym mogę ci pomóc?', 0),
(3370, 'koKR', 'W czym mogę ci pomóc?', 0),
(3378, 'koKR', 'Co cię sprowadza do Świątyni Księżyca, $N?', 0),
(3764, 'koKR', 'Ach tak, ziemia. Arcydruid chce dwudziestu ładunków od każdego poszukiwacza przygód i dwadzieścia ładunków dostanie. Niech ci, którzy spiskują przeciwko nam, zostaną w tyle!', 0),
(3781, 'koKR', 'Pokój i spokój niech będą z tobą, $gprzyjacielu:przyjaciółko;. Przychodzisz w sprawie samego arcydruida, prawda?', 0),
(3782, 'koKR', 'Pokój i spokój niech będą z tobą, $gprzyjacielu:przyjaciółko;. Przychodzisz w sprawie samego arcydruida, prawda?', 0),
(3785, 'koKR', 'Tak, $N? $GWyhodowałeś:Wyhodowałaś; trochę jutroziarna do ważnych badań arcydruida? Tajemnicze właściwości Krateru Un\'Goro z każdym dniem stają się jaśniejsze dzięki twojej pomocy.', 0),
(3803, 'koKR', 'Arcydruid wciąż szuka więcej jutroziarna do dalszych badań Kręgu Cenariona. Przyjmujemy je po dziesięć sztuk i w zamian dajemy skrzynkę przydatnych rzeczy. Gdy będziesz mieć dziesięć, daj mi znać, a odpowiednio cię wynagrodzę.', 0),
(4267, 'koKR', 'Witaj w tej błogosławionej świątyni, $gprzyjacielu:przyjaciółko;. Przepowiedziano mi twoje przybycie z Warowni Lunopiórej. Czy masz raport, który Szandris Lunopióra kazała ci przynieść?', 0),
(4508, 'koKR', 'To głupcy, $N! Nie potrafią nawet pomyśleć, by rozejrzeć się za większym zagrożeniem; ich ślepa nienawiść do Hordy zgubi nas wszystkich. Nie wiem, jakie jeszcze dowody zagrożenia ze strony silithidów mogę im dać, chyba że wrzucę ich do jednego z uli, żeby sami się przekonali!$B$BWybacz, masz dla mnie jakieś wieści?', 0),
(4510, 'koKR', 'Elune\'adore, $N. Co mogę dziś dla ciebie zrobić?', 0),
(4986, 'koKR', 'W imieniu Kręgu Cenariona witam cię w tej enklawie, $N. Co cię do nas sprowadza?', 0),
(5061, 'koKR', 'Wieść o twoim powrocie do Darnassus dotarła tu przed tobą, lecz zanim nauczę cię postaci morskiej, potrzebuję dowodu, że $gprzyswoiłeś:przyswoiłaś; lekcje w Gaju Luny.$B$BCzy masz wisior lwa morskiego?', 0),
(5253, 'koKR', 'Tak?', 0),
(8357, 'koKR', 'Umiesz tańczyć, prawda? Spróbuj tak: prawa nóżka do przodu... prawa nóżka do tyłu... prawa do przodu... i potrząśnij nią...', 0),
(8360, 'koKR', 'Umiesz tańczyć, prawda? Spróbuj tak: prawa nóżka do przodu... prawa nóżka do tyłu... prawa do przodu... i potrząśnij nią...', 0),
(8446, 'koKR', 'Tak?', 0),
(12773, 'koKR', '$n, $gmój synu:moja córko;. Znów zostajemy wciągnięci w konflikt, który może rozbić wszystko, co znamy. Dobrze, że ktoś o twoich talentach wspiera swoją siłą obronę tego drzewa świata.', 0),
(14054, 'koKR', 'Jak idzie z tymi plackami?', 0),
(14060, 'koKR', 'Jak idzie z tymi plackami?', 0),
(14409, 'koKR', 'Wygląda na to, że mam chwilę na rozmowę. W jakiej sprawie?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(661, 0, 'koKR', 'Witaj. Co cię sprowadza do rodu Carevinów? Czy chcesz pomóc Carevinom w walce z nieumarłymi?', 0),
(3453, 0, 'koKR', 'Mogę ci w czymś pomóc, $n? Jeśli nie, muszę się zająć pewną dostawą.', 0),
(3616, 0, 'koKR', 'Wiatr szepcze do tych, którzy słuchają...$B$BSłyszysz go?', 0);
