INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(396, 'koKR', 'Elune spełniła moje prośby. Życie moich poległych towarzyszy nie pójdzie na marne, a ja pomszczę ich śmierć Kosą Eluny. To prastara rzecz: gałąź z pokręconego, sękatego drewna, które może być starsze nawet od kaldorei.$B$BPrzez wiele godzin badałam narzędzie, którym obdarzyła mnie bogini. Z pewnością nie jest to zwykła broń ani też zwykłe magiczne narzędzie. Przy niej... zdaje się, że bariery czasu i przestrzeni słabną.$B$BTrzymając Kosę', 0),
(397, 'koKR', 'w dłoniach, ujrzałam wizję chaosu. Wilkoludzie... worgeni... walczyli z niewiarygodnym wrogiem. Worgeni walczyli dziko, jak przystało ich prymitywnej rasie, lecz ich wróg nie ustępował: Władcy Szmaragdowego Płomienia.$B$BWtedy właśnie pojęłam prawdziwą moc Kosy. Skupiając się na niej, zyskałam zdolność porozumiewania się z worgenami. Nie była to jednak mowa. Było to coś innego... czego nie potrafiłabym opisać.$B$BLiczyło się tylko to, że worgeni mnie usłyszeli', 0),
(398, 'koKR', 'i zrozumieli. Gdy przelewałam w Kosę coraz więcej energii, bariery słabły jeszcze bardziej i zdołałam sprowadzić worgenów do naszego świata. Za pierwszym razem przyzwałam ich trzydziestu. Poszli za mną do boju i z ich brutalną siłą na moje rozkazy rozszarpaliśmy demony Spaczonej Kniei.$B$BElune spełniła moje prośby. Las zostanie oczyszczony.$B$B$BOby błogosławieństwo Eluny spoczywało na mnie, dopóki nie ukończę swego dzieła.', 0),
(399, 'koKR', 'Wszystko idzie dobrze. Przyzwałam więcej worgenów, by walczyli u mego boku. Choć są prostego umysłu, wykazują imponującą zdolność do koordynowania ataków i działania w grupie.$B$BWskazałam przywódców w ich stadach. To im powierzyłam dowództwo nad małymi oddziałami wojowników. Uderzamy jednocześnie z wielu miejsc w lesie, a moja kampania przeciw demonom przynosi owoce.$B$B$BOby błogosławieństwo Eluny spoczywało na mnie, dopóki nie ukończę swego dzieła.', 0),
(400, 'koKR', 'Jedno stado przepadło. Wysłałam worgenów, by przeczesali las i wskazali miejsca skażone przez demony, lecz nie wrócili. Zaczynam się niepokoić o przywódców, którym powierzyłam władzę. Są prostego umysłu, a tę odrobinę władzy, którą im dałam, naciągają do granic. Czy tracę kontrolę? Może na razie przestanę przyzywać kolejnych worgenów.$B$B$BOby błogosławieństwo Eluny spoczywało na mnie, dopóki nie ukończę swego dzieła.', 0),
(401, 'koKR', 'Choć nie przyzywałam już kolejnych worgenów, ich liczba wciąż rośnie. To tak, jakby Kosa nie potrzebowała już mojego udziału w przyzywaniu. To niepokojące. Zebrałam tyle stad, ile zdołałam znaleźć, i rozkazałam im pozostać przy Kaplicy Mel\'Thandris.$B$BTymczasem przeszukałam biblioteki Darnassus i zasięgnęłam rady Kręgu Pradawnych na Mrocznym Wybrzeżu. Nie znalazłam ani strzępu wiadomości o tych worgenach. Słyszałam doniesienia,', 0),
(402, 'koKR', 'szepty o czarodzieju z Kirin Toru imieniem Arugal. Z tego, co słyszałam, możliwe, że on również przyzywał worgenów. Chciałabym zasięgnąć rady tego czarodzieja – choćby było to niemiłe – i dowiedzieć się, co wie.$B$BWorgeni są niebezpieczni i pragnę powstrzymać ich napływ. Jutro udam się do portu na Pustkowiach i wykupię miejsce na statku do Nowego Świata.$B$B$BOby błogosławieństwo Eluny spoczywało na mnie, dopóki nie ukończę swego dzieła.', 0),
(1844, 'koKR', 'W miarę upływu stuleci nowa społeczność nocnych elfów rosła w siłę i rozprzestrzeniała się po młodym lesie, który nazwali Jesionową Knieją. Wiele stworzeń i gatunków licznych przed Wielkim Rozłamem, takich jak furbolgi i kolcozwierze, pojawiło się ponownie i rozkwitło na tej ziemi. Pod życzliwym przywództwem druidów nocne elfy zaznały bezprecedensowej ery pokoju i spokoju pod gwiazdami.', 0),
(1845, 'koKR', 'Jednak wielu Wysoko Urodzonych, którzy przetrwali, zaczęło odczuwać niepokój. Podobnie jak wcześniej Illidan, padli ofiarą głodu, który zrodziła utrata upragnionej magii. Kusiło ich, by czerpać z energii Studni Wieczności i oddawać się swoim magicznym praktykom. Dath\'Remar, zuchwały i wygadany przywódca Wysoko Urodzonych, zaczął publicznie szydzić z druidów, nazywając ich tchórzami, bo nie chcieli władać magią, która według niego należała im się z prawa.', 0),
(1846, 'koKR', 'Malfurion i druidzi odrzucili argumenty Dath\'Remara i ostrzegli Wysoko Urodzonych, że każde użycie magii będzie karane śmiercią. W zuchwałej i fatalnej w skutkach próbie zmuszenia druidów do uchylenia prawa Dath\'Remar i jego zwolennicy rozpętali nad Jesionową Knieją straszliwą magiczną burzę.', 0),
(1847, 'koKR', 'Druidzi nie potrafili się zdobyć na skazanie na śmierć tak wielu pobratymców, postanowili więc wygnać lekkomyślnych Wysoko Urodzonych ze swoich ziem. Dath\'Remar i jego zwolennicy, zadowoleni, że wreszcie pozbywają się swoich zachowawczych krewniaków, wsiedli na specjalnie zbudowane statki i wypłynęli na morze. Choć żaden z nich nie wiedział, co czeka ich za wodami szalejącego Wiru, pragnęli założyć własną ojczyznę, w której mogliby bezkarnie uprawiać upragnioną magię.', 0),
(1848, 'koKR', 'Wysoko Urodzeni, czyli quel\'dorei, jak przed wiekami nazwała ich Aszara, w końcu przybili do brzegów wschodniej krainy, którą ludzie nazwą Lordaeronem. Zamierzali zbudować własne magiczne królestwo, Quel\'Thalas, i odrzucić zasady nocnych elfów: kult księżyca i nocny tryb życia. Odtąd mieli na zawsze przyjąć słońce i być znani wyłącznie jako wysokie elfy.', 0),
(2083, 'koKR', 'Podczas najazdu Legionu na Jesionową Knieję Illidan został uwolniony ze swojego podziemnego więzienia po dziesięciu tysiącach lat niewoli. Choć starał się zjednać sobie towarzyszy, wkrótce powrócił do swojej prawdziwej natury i pochłonął energię potężnego artefaktu czarnoksiężników, zwanego Czaszką Gul\'dana.', 0),
(2084, 'koKR', 'W ten sposób Illidan zyskał demoniczne cechy i ogromnie spotęgowaną moc. Przejął też część dawnych wspomnień Gul\'dana – zwłaszcza tych o Grobowcu Sargerasa, wyspiarskim lochu, w którym podobno spoczywały szczątki Mrocznego Tytana, Sargerasa.', 0),
(2085, 'koKR', 'Kipiąc mocą i znów mogąc swobodnie przemierzać świat, Illidan wyruszył, by znaleźć własne miejsce w wielkim porządku rzeczy. Kil\'jaeden stanął jednak przed Illidanem i złożył mu propozycję nie do odrzucenia. Kil\'jaeden był rozgniewany klęską Archimonda na Górze Hyjal, ale miał większe zmartwienia niż zemsta.', 0),
(2086, 'koKR', 'Wyczuwając, że jego dzieło, Król Lisz, staje się zbyt potężne, by nad nim panować, Kil\'jaeden rozkazał Illidanowi zniszczyć Ner\'zhula i raz na zawsze położyć kres nieumarłej Pladze. W zamian Illidan miał otrzymać niezmierzoną moc i prawdziwe miejsce wśród pozostałych władców Płonącego Legionu.', 0),
(2087, 'koKR', 'Illidan przystał na to i natychmiast wyruszył, by zniszczyć Mroźny Tron – lodową kryształową skrzynię, w której przebywał duch Króla Lisza. Illidan wiedział, że do zniszczenia Mroźnego Tronu potrzebuje potężnego artefaktu. Korzystając z wiedzy zaczerpniętej ze wspomnień Gul\'dana, postanowił odszukać Grobowiec Sargerasa i zawładnąć szczątkami Mrocznego Tytana.', 0),
(2088, 'koKR', 'Upomniał się o dawne długi Wysoko Urodzonych i wywabił wężowe nagi z ich mrocznych podmorskich leży. Pod wodzą przebiegłej czarownicy, lady Vash, nagi pomogły Illidanowi dotrzeć na Strzaskane Wyspy, gdzie podobno znajdował się Grobowiec Sargerasa.', 0),
(2089, 'koKR', 'Gdy Illidan wyruszył z nagami, strażniczka Maiev Cienista Pieśń zaczęła go ścigać. Maiev przez dziesięć tysięcy lat była strażniczką więzienia Illidana i z rozkoszą myślała o jego ponownym pojmaniu. Illidan przechytrzył jednak Maiev i jej Strażników i mimo ich wysiłków zdobył Oko Sargerasa. Z potężnym Okiem w ręku Illidan udał się do dawnego miasta czarodziejów, Dalaranu.', 0),
(2090, 'koKR', 'Wzmocniony mocą linii mocy przecinających miasto, Illidan użył Oka, by rzucić niszczycielskie zaklęcie na cytadelę Króla Lisza, Lodową Koronę, w odległej Północnej Grani. Atak Illidana strzaskał obronę Króla Lisza i rozdarł sam dach świata. W ostatniej chwili niszczycielskie zaklęcie Illidana zostało przerwane, gdy na pomoc Maiev przybyli jego brat Malfurion i kapłanka Tyrande.', 0),
(2091, 'koKR', 'Wiedząc, że Kil\'jaeden nie będzie zadowolony z jego porażki w niszczeniu Mroźnego Tronu, Illidan uciekł do jałowego wymiaru zwanego Rubieżą – ostatniej pozostałości Draenoru, dawnego ojczystego świata orków. Tam zamierzał umknąć gniewowi Kil\'jaedena i zaplanować kolejne posunięcia.', 0),
(2092, 'koKR', 'Powstrzymawszy Illidana, Malfurion i Tyrande wrócili do domu, do Jesionowej Kniei, by czuwać nad swoim ludem. Maiev jednak nie zamierzała tak łatwo się poddać i podążyła za Illidanem do Rubieży, zdecydowana postawić go przed sądem.', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(50025, 'koKR', 'Wiatr szepcze do tych, którzy słuchają...$B$BSłyszysz go?', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1179, 'koKR', '%s zaczyna poruszać Kamieniem Relu nad dwiema skamieniałościami.', '', 0),
(1180, 'koKR', 'Na gwiazdy! Przywołano ducha!', '', 0),
(1181, 'koKR', 'To prawdziwa tajemnica przeszłości! I zarazem klucz do naszej przyszłości!', '', 0),
(1216, 'koKR', '%s studiuje pergamin z Tomu zmierzchu...', '', 0),
(1219, 'koKR', '%s kontynuuje medytację...', '', 0),
(3742, 'koKR', 'Potrzebujesz zaopatrzenia alchemicznego? A może masz do mnie inną sprawę?', '', 0),
(4407, 'koKR', 'Chwała Elunie! Od wielu lat nikt mnie nie odwiedzał.', '', 0),
(4408, 'koKR', 'Chcę usłyszeć twoją opowieść.', 'Chcę usłyszeć twoją opowieść.', 0),
(4409, 'koKR', 'Za młodu, jeszcze na Mrocznym Wybrzeżu, zetknąłem się z grupą podejrzanych typów zwanych Młotem Zmierzchu. Kilku z nich się ze mną zaprzyjaźniło i, ku mojemu wstydowi, porzuciłem wiarę w Elunę, a przyjąłem jad Młota Zmierzchu.$B$BDopiero wizja zesłana mi przez Elunę wyrwała mnie z marazmu, w który popadłem jako wyznawca Przedwiecznych.$B$BNa znak skruchy zacząłem pisać modlitwę do Eluny.', '', 0),
(4410, 'koKR', 'Mów dalej, Zamaelu.', 'Mów dalej, Zamaelu.', 0),
(4411, 'koKR', 'Na tabliczce z czystego złota wyryłem całą swoją skruchę, wstyd, żal i smutek. Niestety, Młot Zmierzchu znalazł tabliczkę i okrzyknął mnie bluźniercą. Stracono mnie bez sądu, a moja modlitwa do Eluny pozostała niedokończona. Teraz jako duch jestem przykuty do tego świata i nie mogę odejść do Otchłani; trzymają mnie w tej klatce jako przestrogę dla wszystkich, którzy chcieliby zdradzić wiarę Młota Zmierzchu.\n', '', 0),
(4412, 'koKR', 'Pozwól mi to przemyśleć, Zamaelu.', 'Pozwól mi to przemyśleć, Zamaelu.', 0),
(4643, 'koKR', 'Wszędzie spiski, mówię ci. Są tacy, którym brak wizji, by zrozumieć, co robię, i chcieliby trzymać mnie spętanego w zapomnieniu!$B$BNie wdepnij w ziemię.', '', 0),
(4645, 'koKR', 'Co robię? Brak ci wizji? Jestem marzycielem, $gdobry panie:dobra pani;, i marzę o lepszej przyszłości dla nas wszystkich. To oczywiste, że jestem wizjonerem.$B$BSą jednak tacy, którzy chcą nas trzymać w bagnie banału. Powiedziałem mu, że jestem marzycielem, a arcydruid Jeleniorogi odparł: „Cóż, świat potrzebuje też kopaczy rowów”.$B$BDopóki nie zerwiemy z siebie kajdan banału, będę pomagał Kręgowi Cenariona, przerzucając te kupki ziemi.', '', 0),
(4958, 'koKR', 'Witaj, $N. Jeśli szukasz wyrobów skórzanych i zaopatrzenia dla kaletników, $gtrafiłeś:trafiłaś; do właściwego paladyna na półemeryturze.', '', 0),
(5424, 'koKR', 'Witaj w Banku Darnassus. Prowadzimy rachunki i oferujemy skrytki depozytowe na cenne przedmioty. Czy $gma pan:ma pani; już u nas rachunek?', 'Witaj w Banku Darnassus. Prowadzimy rachunki i oferujemy skrytki depozytowe na cenne przedmioty. Czy $gma pan:ma pani; już u nas rachunek?', 0),
(6045, 'koKR', 'Tak, mówię językiem, który rozumiesz. Nie jesteśmy zwierzętami, a jednak większość twoich pobratymców wciąż tak nas traktuje! Nasze różnice bledną jednak wobec tragedii, która spadła na tę krainę. Proszę, odłóż na bok spory z moim ludem i wysłuchaj mojej umierającej prośby.$B$BPrzybyłem tu, by naprawić, co się da, a wszystko pójdzie na marne, jeśli mi nie pomożesz. Proszę cię o tę pomoc ostatnim tchnieniem.', '', 0),
(6089, 'koKR', 'Będę o tym pamiętać, gdy następnym razem natknę się na jedno z tych stworzeń.', 'Będę o tym pamiętać, gdy następnym razem natknę się na jedno z tych stworzeń.', 0),
(6482, 'koKR', 'Z łaski Eluny z radością oferuję ci najlepszego wierzchowca na całym Teldrassilu, a może i na świecie – nocną szablobestię. Od lat armia Strażniczek polega na tych towarzyszach.$B$BNie spiesz się, $gprzyjacielu:przyjaciółko;, i obejrzyj każdą z nich, ile zechcesz. Na pewno się nie zawiedziesz.', 'Z łaski Eluny z radością oferuję ci najlepszego wierzchowca na całym Teldrassilu, a może i na świecie – nocną szablobestię. Od lat armia Strażniczek polega na tych towarzyszach.$B$BNie spiesz się, $gprzyjacielu:przyjaciółko;, i obejrzyj każdą z nich, ile zechcesz. Na pewno się nie zawiedziesz.', 0),
(7448, 'koKR', 'Witaj, $N. Jesteś mile $gwidziany:widziana; w Nocnym Azylu i w całym Gaju Luny. Krąg Cenariona wita wszystkie istoty, które szanują władzę i prawa natury.$B$BPodczas pobytu tutaj dbaj, proszę, o zachowanie równowagi we wszystkim. Zakłócanie spokoju nie jest tu mile widziane, a nasi strażnicy są wyszkoleni, by bez wahania przerywać wszelkie walki.', '', 0),
(7532, 'koKR', 'Mogę cię nauczyć tajników jazdy na tygrysie, o ile masz dość złota, by zapłacić za lekcję!', 'Mogę cię nauczyć tajników jazdy na tygrysie, o ile masz dość złota, by zapłacić za lekcję!', 0),
(7641, 'koKR', 'Co mogę dla ciebie zrobić, moje dziecko?', 'Co mogę dla ciebie zrobić, moje dziecko?', 0),
(7689, 'koKR', '', 'Elune\'adore, $gbracie:siostro;. Jesteś tu $gmile widziany:mile widziana;.', 0),
(7728, 'koKR', '', 'Nawet drobna zmiana składników mikstury może całkowicie odmienić jej działanie. Cierpliwość i precyzja, $gmłodzieńcze:dziewczę; – przydadzą ci się na każdej ścieżce życia.', 0),
(7759, 'koKR', '', 'Za każdym razem, gdy warzę tę miksturę, leczy coraz mniej ran, choć używam tych samych składników. Wniosek może być tylko jeden: rośliny się zmieniają. Nie potrafię powiedzieć, dlaczego ani w co.', 0),
(7874, 'koKR', '', 'Bogini obdarzyła mnie mądrością, $gnieznajomy:nieznajoma;. Jeśli taka jest jej wola, przekażę ją tobie.', 0),
(7902, 'koKR', 'To prawda, mam umiejętności, których mogę nauczyć tych, którzy są tego godni. Czy należysz do nich?', '', 0),
(7955, 'koKR', '', 'Jeśli interesuje cię szycie ze skóry, z pewnością $gtrafiłeś:trafiłaś; we właściwe miejsce. Faldron i Telonis to prawdziwi artyści, a ja mam nadzieję wiele się od nich nauczyć.', 0),
(7994, 'koKR', 'Darianna jest obiecująca, ale ma w sobie tyle energii, że trudno jej usiedzieć w miejscu i słuchać. Przy jej sile i zwinności obawiam się, że niedługo zostanie wezwana do walki. Musimy ją szybko wyszkolić.', '', 0),
(8045, 'koKR', 'Nie próbuj narzucać skórze swojej woli. Pozwól raczej, by jej naturalne skłonności podpowiedziały, jaki kształt i jakie przeznaczenie przybierze. To nie bitwa, którą trzeba wygrać. Pracuj ze skórą, a nie przeciw niej.', '', 0),
(8083, 'koKR', '', 'Nie ma lepszego sposobu na oczyszczenie umysłu niż tkanie.', 0),
(8157, 'koKR', '', 'Cóż za piękny dzień! Aż mnie natchnął do nowego wzoru.', 0),
(8417, 'koKR', 'Niestety, $N, nie cieszysz się najwyższym poważaniem Darnassus i nocnych elfów z Teldrassilu. Dopiero gdy udowodnisz nam swoją wartość czynami – nie samymi słowami – pozwolę ci obejrzeć moich wierzchowców.', 'Niestety, $N, nie cieszysz się najwyższym poważaniem Darnassus i nocnych elfów z Teldrassilu. Dopiero gdy udowodnisz nam swoją wartość czynami – nie samymi słowami – pozwolę ci obejrzeć moich wierzchowców.', 0),
(8435, 'koKR', 'Nauczę cię jazdy wierzchem dopiero wtedy, gdy nocne elfy z Darnassus obdarzą cię najwyższym poważaniem, $N.', 'Nauczę cię jazdy wierzchem dopiero wtedy, gdy nocne elfy z Darnassus obdarzą cię najwyższym poważaniem, $N.', 0),
(8695, 'koKR', 'Nie słuchaj serc świata – odpowiedź leży w tobie. Znasz prawdę.', '', 0),
(8879, 'koKR', '', 'Gracji, z jaką walczę, nie mogę cię nauczyć, ale mogę cię nauczyć posługiwania się różnymi rodzajami broni.', 0),
(8880, 'koKR', '', 'Jeśli wolisz, mogę cię skierować do innych mistrzów broni. Co cię interesuje?', 0),
(9534, 'koKR', 'Czy słyszałeś kiedyś o miejscu zwanym Srogomłoty?', 'Czy słyszałeś kiedyś o miejscu zwanym Srogomłoty?', 0),
(9535, 'koKR', 'Owszem, ale znam je pod prawdziwym imieniem – Eldre\'Thalas. Przed wieloma, wieloma laty było bastionem magicznej potęgi nocnych elfów.$B$BZnasz Eldre\'Thalas, $gmłodzieńcze:dziewczę;? Można by rzec, że to zbieg okoliczności w obliczu mojego obecnego kłopotu... ale ja nie wierzę w zbiegi okoliczności.', '', 0),
(9536, 'koKR', 'Czemu mówisz, że to zbieg okoliczności, Rabine?', 'Czemu mówisz, że to zbieg okoliczności, Rabine?', 0),
(9537, 'koKR', 'Wysłannicy Kręgu Cenariona odkryli niepokojące wieści o obecnej sytuacji w Eldre\'Thalas. Nie wiem, co z tym począć, i bez wątpienia wkrótce poszukam pomocy u sprawnych istot, które potrafią sobie radzić w walce.$B$BAby jednak właściwie działać w Eldre\'Thalas, trzeba poznać dzieje przedmiotu zwanego Owocem Płodności.', '', 0),
(9538, 'koKR', 'Owocem Płodności?', 'Owocem Płodności?', 0),
(9539, 'koKR', 'W dawnych wiekach Eldre\'Thalas było ośrodkiem magicznej potęgi, a ci, którzy przebywali w jego uświęconych salach, władali ogromną mocą. Jedną z takich nocnych elfek była Millicent Pogodna – przyrodniczka, która wolą przelewała moc samej natury w potężne artefakty, jakie wykuwała.$B$BOwoc Płodności był jej największym dziełem... w specjalnie przygotowanej księżycowej studni wyhodowała egzotyczne, bujne pnącze, przesycone aurą ochrony i wzrostu. Dzięki niemu rozkwitało całe Eldre\'Thalas.', '', 0),
(9540, 'koKR', 'Ale coś poszło nie tak, prawda?', 'Ale coś poszło nie tak, prawda?', 0),
(9541, 'koKR', 'Niestety, zawsze tak się zdaje. Ja – podobnie jak cały Krąg Cenariona – zakładałem, że dzieło Milli zostało zniszczone podczas Wojny Starożytnych. Jak się dowiedziałem, to dalekie od prawdy.$B$BOwoc Płodności przetrwał... choć teraz znany jest jako spaczone pnącze. Kazi go demoniczny władca tej części Eldre\'Thalas, Alzzin Kształtujący Dzicz.', '', 0),
(9542, 'koKR', 'Co by się stało, gdyby Owoc Płodności – czy też spaczone pnącze – uległ całkowitemu skażeniu?', 'Co by się stało, gdyby Owoc Płodności – czy też spaczone pnącze – uległ całkowitemu skażeniu?', 0),
(9543, 'koKR', 'Nie... potrafię sobie tego nawet wyobrazić, $n. Wiem tylko, że nie dopuszczę do tego. Zostanie zniszczony – jeśli nie dla naszego bezpieczeństwa przed demonicznym skażeniem, to przez pamięć o Millicent Pogodnej... o Milli...$B$BI tu, $gprzyjacielu:przyjaciółko;, liczę na ciebie.', '', 0),
(9545, 'koKR', 'Porozmawiaj ze mną, $n – jeśli zechcesz, Krąg Cenariona chętnie przyjmie twoją hojną ofertę pomocy. Zagrożenie ze strony spaczonego pnącza z Eldre\'Thalas jest naprawdę poważne.', '', 0),
(9826, 'koKR', 'Przysięgam... jeśli Quint jeszcze raz podrzuci mi rybacką larwę, zetnę jego drzewo moim wcale-nie-tak-zardzewiałym mieczem.', '', 0),
(9900, 'koKR', 'Witaj, $gprzyjacielu:przyjaciółko; – czy mogę prosić o chwilę twojego czasu...$B$BWiele wycierpieliśmy w trudach i znojach zakładania Teldrassilu. Jakby ciągłych zmagań tych czasów było mało, teraz dotkliwie brakuje nam tkanin. Jeśli możesz się jakimiś podzielić, proszę, przekaż je nam. Pomagając nam, z pewnością zasłużysz na wdzięczność nocnych elfów na całym świecie!', '', 0),
(10354, 'koKR', '', 'Witaj, $N. Chcesz wesprzeć Strażniczki Srebrnego Skrzydła w walce w Wąwozie Wojennej Pieśni?', 0),
(10525, 'koKR', 'No, $gchłopcze:dziewczyno;, $ggotów:gotowa; ruszyć do Doliny Alterak i dać Hordzie posmakować tego, o co się sama prosi?', '', 0),
(10787, 'koKR', '', 'Może mam dziewięćdziesiąt dziewięć problemów, ale taniec do nich nie należy! Wesołych Zaduszników, $n!', 0),
(10800, 'koKR', '', 'Może mam dziewięćdziesiąt dziewięć problemów, ale taniec do nich nie należy! Wesołych Zaduszników, $n!', 0),
(11191, 'koKR', 'Ściany komnaty drżą. Coś się dzieje...', 'Ściany komnaty drżą. Coś się dzieje...', 0),
(11193, 'koKR', 'Bądź $gniezłomny:niezłomna;, $gczempionie:czempionko;. Wiem, dlaczego tu jesteś, i wiem, czego szukasz. Eranikus nie odda odłamka dobrowolnie. Został wypaczony... wypaczony przez tę samą siłę, którą chcesz zniszczyć.', '', 0),
(11194, 'koKR', 'Naprawdę cię to dziwi? Tak trudno uwierzyć, że moc Przedwiecznego mogłaby sięgnąć nawet do wnętrza Snu? Tak jest – Eranikus, tyran Snu, toczy wojnę z nami wszystkimi. Koszmar podąża śladem zniszczenia, jakie za sobą zostawia.', '', 0),
(11195, 'koKR', 'Zrozum jedno: Eranikus niczego nie pragnie bardziej, niż zostać sprowadzonym ze Snu do Azeroth. Gdy tylko się wydostanie, nie cofnie się przed niczym, by zniszczyć moje fizyczne wcielenie. To jednak jedyny sposób, byś $godzyskał:odzyskała; odłamek berła.', '', 0),
(11196, 'koKR', 'Sprowadzisz go z powrotem na ten świat, $gczempionie:czempionko;.', '', 0),
(11558, 'koKR', 'Gdzie jest Nestor Ostrolist?', 'Gdzie jest Nestor Ostrolist?', 0),
(11559, 'koKR', 'Nestor Ostrolist mieszka w wiosce Dolanaar na szczycie Teldrassilu.', 'Nestor Ostrolist mieszka w wiosce Dolanaar na szczycie Teldrassilu.', 0),
(11561, 'koKR', 'Gdzie jest Nestor Gwiezdna Przędza?', 'Gdzie jest Nestor Gwiezdna Przędza?', 0),
(11562, 'koKR', 'Nestor Gwiezdna Przędza przebywa na plaży niedaleko Lor\'danel na Mrocznym Wybrzeżu.', 'Nestor Gwiezdna Przędza przebywa na plaży niedaleko Lor\'danel na Mrocznym Wybrzeżu.', 0),
(12458, 'koKR', 'Nasza droga to droga czystości i prawości w Światłości.', 'Nasza droga to droga czystości i prawości w Światłości.', 0),
(12459, 'koKR', 'W Światłości jesteśmy jednym, $gbracie:siostro;, ale nie mogę cię szkolić.', 'W Światłości jesteśmy jednym, $gbracie:siostro;, ale nie mogę cię szkolić.', 0),
(13485, 'koKR', 'Choć możemy wiele nauczyć inne rasy Przymierza, równie wiele możemy się od nich nauczyć. Miej oczy, uszy i umysł otwarte, $N.', '', 0),
(13486, 'koKR', '', 'Bądź pozdrowiony, $N.', 0),
(13488, 'koKR', '', 'Witaj. Jestem Obrończyni Palanaar, wędrowna paladynka Światłości. Przybyłam tu, by służyć pomocą nocnym elfom.', 0),
(14411, 'koKR', '', 'Łaska Eluny niech będzie z tobą. Czym mogę służyć?', 0),
(14775, 'koKR', 'Ta kraina została spustoszona przez katastrofę. Choć być może nie wyznajesz naszej filozofii, $N, gorąco cię proszę, zrób, co w twojej mocy, by pomóc w jej uzdrowieniu.', 'Ta kraina została spustoszona przez katastrofę. Choć być może nie wyznajesz naszej filozofii, $N, gorąco cię proszę, zrób, co w twojej mocy, by pomóc w jej uzdrowieniu.', 0),
(14776, 'koKR', 'Witaj, $gbracie:siostro;. Jak mogę cię dziś poprowadzić?', 'Witaj, $gbracie:siostro;. Jak mogę cię dziś poprowadzić?', 0),
(16156, 'koKR', 'Festiwal Księżyca ma dla nocnych elfów szczególne znaczenie. Szukamy mądrości naszych nestorów na całym świecie.', 'Festiwal Księżyca ma dla nocnych elfów szczególne znaczenie. Szukamy mądrości naszych nestorów na całym świecie.', 0),
(16158, 'koKR', 'Mam wrażenie, że wszyscy chcą mnie pocałować pod jemiołą.', 'Mam wrażenie, że wszyscy chcą mnie pocałować pod jemiołą.', 0),
(16181, 'koKR', 'Obchody Festiwalu Księżyca w Gaju Luny trwają w najlepsze. Możesz wybrać się tam pieszo albo skorzystać z transportu, który oferują druidzi w Enklawie Cenariona.', 'Obchody Festiwalu Księżyca w Gaju Luny trwają w najlepsze. Możesz wybrać się tam pieszo albo skorzystać z transportu, który oferują druidzi w Enklawie Cenariona.', 0),
(16183, 'koKR', 'Niezliczone światy mam już za sobą, ale na żadnym nie było święta tak radosnego jak ta Zimowa Uczta. Wybierz się do Żelaznej Kuźni, wielkiego miasta krasnoludów, i przekonaj się na własne oczy.', 'Niezliczone światy mam już za sobą, ale na żadnym nie było święta tak radosnego jak ta Zimowa Uczta. Wybierz się do Żelaznej Kuźni, wielkiego miasta krasnoludów, i przekonaj się na własne oczy.', 0),
(16966, 'koKR', 'Proszę, usiądź i rozgość się.', 'Proszę, usiądź i rozgość się.', 0),
(20541, 'koKR', 'Władania kuszą może cię nauczyć Woo Ping, ludzki mistrz broni w Arsenale Wellera w Wichrogrodzie, Handiir, mistrz broni draenei na Tarasie Handlarzy w Exodarze, albo Bixi Trzęsibuch, gnomia mistrzyni broni w Orężu „Granica Lasu” w Żelaznej Kuźni.', 'Władania kuszą może cię nauczyć Woo Ping, ludzki mistrz broni w Arsenale Wellera w Wichrogrodzie, Handiir, mistrz broni draenei na Tarasie Handlarzy w Exodarze, albo Bixi Trzęsibuch, gnomia mistrzyni broni w Orężu „Granica Lasu” w Żelaznej Kuźni.', 0),
(23260, 'koKR', 'Świętować narodziny kolejnego śmiertelnego wroga to rzecz co najmniej dziwna. Mimo to przyłączymy się do zabawy naszych sojuszników.', 'Świętować narodziny kolejnego śmiertelnego wroga to rzecz co najmniej dziwna. Mimo to przyłączymy się do zabawy naszych sojuszników.', 0),
(23294, 'koKR', 'Przeklęte niech będzie to wypaczanie nocy. Ale cukierki są dobre.', 'Przeklęte niech będzie to wypaczanie nocy. Ale cukierki są dobre.', 0),
(24336, 'koKR', 'Za rok przebiorę się za korsarza albo za skrytobójcę.', 'Za rok przebiorę się za korsarza albo za skrytobójcę.', 0),
(24338, 'koKR', 'Za rok przebiorę się za korsarza albo za skrytobójcę.', 'Za rok przebiorę się za korsarza albo za skrytobójcę.', 0),
(26304, 'koKR', 'Hmm...', 'Hmm...', 0),
(27428, 'koKR', 'Co tu robisz?', 'Co tu robisz?', 0),
(33124, 'koKR', 'Miłogrody to czas, gdy druidzi Azeroth świętują odrodzenie życia. Jajka są symbolem płodności i doskonałym sposobem, by wszystkich wprawić w świąteczny nastrój, nie sądzisz?', 'Miłogrody to czas, gdy druidzi Azeroth świętują odrodzenie życia. Jajka są symbolem płodności i doskonałym sposobem, by wszystkich wprawić w świąteczny nastrój, nie sądzisz?', 0),
(35097, 'koKR', 'Jakże to święto kontrastuje z typowym zachowaniem ludzi. Kto by pomyślał, że lud tak nienasycenie zachłanny uczyni święto z dawania i dzielenia się?$B$BMiło na to patrzeć. Darnassus powinno ze wszystkich sił je wspierać i do niego zachęcać.', 'Jakże to święto kontrastuje z typowym zachowaniem ludzi. Kto by pomyślał, że lud tak nienasycenie zachłanny uczyni święto z dawania i dzielenia się?$B$BMiło na to patrzeć. Darnassus powinno ze wszystkich sił je wspierać i do niego zachęcać.', 0),
(36428, 'koKR', 'Strażniczko, chcę rozmawiać z waszą Wielką Kapłanką.', '', 0),
(36429, 'koKR', 'Muszę? Wątpię, by Tyrande miała pilniejsze sprawy.', '', 0),
(36430, 'koKR', 'Pokusa mocy jest wielka. Popełniono błędy.', '', 0),
(36431, 'koKR', 'Nie wrócę, dopóki nie zostanę wysłuchany. Za dużo jest na szali.', '', 0),
(36432, 'koKR', 'Wiatr niesie zmiany i nie możemy ich lekceważyć. Przybyłem z prochu i ruin przeszłości, by dojść do porozumienia.', '', 0),
(36433, 'koKR', 'Wkrótce może nadejść czas, gdy kaldorei będą potrzebować wiedzy i umiejętności, które możemy im zaoferować.', '', 0),
(36434, 'koKR', 'Poczekam, Strażniczko... ale doczekam się audiencji.', '', 0),
(36435, 'koKR', 'Uspokój się, Strażniczko. Nie zamierzam z niej korzystać. Ja tylko... wspominam.', '', 0),
(36436, 'koKR', 'Dość. Przez wieki byłem od tego odcięty. Studnia w tej świątyni może być tylko bladym widmem Studni Wieczności, ale wciąż ma w sobie to samo... piękno. Czystość.', '', 0),
(36437, 'koKR', 'Zapomniałem.', '', 0),
(36438, 'koKR', 'Nie sądzę, by podziw i tęskne myśli łamały przyjęte obyczaje.', '', 0),
(36439, 'koKR', 'To ty mnie zaczepiłaś tylko za to, że patrzyłem. Wciąż czekam na audiencję u Tyrande.', '', 0),
(36440, 'koKR', '%s z westchnieniem spogląda na księżycową studnię.', '', 0),
(36446, 'koKR', '', 'Musisz zaczekać na audiencję.', 0),
(36447, 'koKR', '', 'Masz czelność zjawiać się na Teldrassilu, Wysoko Urodzony. Twój ród nie jest tu mile widziany. Nie zapomnieliśmy Wojny Starożytnych ani umysłów, które za nią stały.', 0),
(36448, 'koKR', '', 'A my nie chcemy, by te błędy się powtórzyły. Wracaj na wygnanie.', 0),
(36449, 'koKR', '', 'Oderwij wzrok od księżycowej studni, wygnańcze. Nie tobie władać mocą, która w niej drzemie.', 0),
(36450, 'koKR', '', 'Wspominasz swoją zdradę?', 0),
(36451, 'koKR', '', 'Uważaj, Wysoko Urodzony.', 0),
(36452, 'koKR', '', 'W swoim czasie.', 0),
(36456, 'koKR', 'Chyba nie powinno mnie dziwić to chłodne przyjęcie. Długo się ukrywaliśmy, a rozłąka z naszymi pobratymcami była konieczna.$b$bTen czas jednak minął. Czy mieszkańcy tego młodego drzewa nas zaakceptują, czy nie, Wysoko Urodzeni wychodzą na światło dzienne i nie odwrócimy się od tego, kim jesteśmy.', '', 0),
(39743, 'koKR', '', 'Siły armii Strażniczek powstrzymują Hordę w całym Kalimdorze. Choć wojna trwa w Jesionowej Kniei i Górach Szponogłazach, nasze siły są potrzebne także tutaj, by chronić te ostatnie dzikie ostępy i nie pozwolić wrogom zdobyć kolejnych przyczółków.', 0),
(40421, 'koKR', 'Mówię ci, ten Coren Bimberhaust to wariat.\nTo nie MOJA wina, że nie zaprosili go do konkursu na Festiwalu Piwa! Ale to nie przeszkodziło jemu i jego kumplom z Czarnorytych poturbować moich pracowników i wypić całe moje piwo.\nKtoś musi położyć temu kres!', '', 0);
